#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define the GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
#define GPIO_LINE_1 2
#define GPIO_LINE_2 3

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line1;
struct gpiod_line *line2;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully.\n", sig);

    // Release GPIO lines
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line 2
    line1 = gpiod_chip_get_line(chip, GPIO_LINE_1);
    if (!line1) {
        perror("Error getting GPIO line 1");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line 3
    line2 = gpiod_chip_get_line(chip, GPIO_LINE_2);
    if (!line2) {
        perror("Error getting GPIO line 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line 1 as output
    if (gpiod_line_request_output(line1, "gpio-output", 0) < 0) {
        perror("Error requesting GPIO line 1 as output");
        gpiod_line_release(line2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line 2 as output
    if (gpiod_line_request_output(line2, "gpio-output", 0) < 0) {
        perror("Error requesting GPIO line 2 as output");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop to toggle the GPIO lines
    while (1) {
        // Set GPIO line 1 HIGH
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("Error setting GPIO line 1 HIGH");
            break;
        }

        // Set GPIO line 2 LOW
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("Error setting GPIO line 2 LOW");
            break;
        }

        printf("GPIO %d: HIGH, GPIO %d: LOW\n", GPIO_LINE_1, GPIO_LINE_2);

        // Wait for 0.1 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&sleep_time, NULL);

        // Set GPIO line 1 LOW
        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("Error setting GPIO line 1 LOW");
            break;
        }

        // Set GPIO line 2 HIGH
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("Error setting GPIO line 2 HIGH");
            break;
        }

        printf("GPIO %d: LOW, GPIO %d: HIGH\n", GPIO_LINE_1, GPIO_LINE_2);

        // Wait for 0.1 seconds
        sleep_time.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO lines and close chip (in case of error)
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 1;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    int value;
    int ret;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d output control started. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (keep_running) {
        // Read current value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        // Validate value
        if (value != 0 && value != 1) {
            fprintf(stderr, "Invalid GPIO value: %d\n", value);
            continue; // Skip printing and sleep
        }

        // Print value
        printf("GPIO %d: %d\n", GPIO_PIN, value);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Release GPIO line
    if (line) {
        gpiod_line_release(line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("GPIO %d output control stopped.\n", GPIO_PIN);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096

int main() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) return 1;
    ioctl(fd, I2C_SLAVE, ADS1115_ADDR);

    uint8_t config[3] = {CONFIG_REG, 0xC2, 0x83};
    write(fd, config, 3);
    usleep(9000);

    uint8_t reg = CONVERSION_REG;
    write(fd, &reg, 1);
    uint8_t data[2];
    read(fd, data, 2);
    int16_t raw = (data[0] << 8) | data[1];
    double voltage = (raw * REF_VOLTAGE) / 32768.0;
    printf("Voltage: %.3f V\n", voltage);
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// MLX90614 I2C address
#define MLX90614_ADDR 0x5A

// MLX90614 register addresses
#define TA_REG 0x06
#define TOBJ1_REG 0x07

// I2C device file
#define I2C_DEV "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the I2C device
int16_t read_i2c_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }
    return (int16_t)((buf[1] << 8) | buf[0]);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read ambient temperature
        int16_t ta = read_i2c_word(i2c_fd, TA_REG);
        if (ta == -1) {
            fprintf(stderr, "Error reading ambient temperature. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Read object temperature
        int16_t to = read_i2c_word(i2c_fd, TOBJ1_REG);
        if (to == -1) {
            fprintf(stderr, "Error reading object temperature. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Print the temperatures
        printf("Ambient Temperature: %d m°C, Object Temperature: %d m°C\n", ta, to);

        // Wait 5 seconds
        sleep(5);
    }

    return 0;
}

