{
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line 1
    gpio_line_1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!gpio_line_1) {
        perror("Error getting GPIO line 1");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line 2
    gpio_line_2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!gpio_line_2) {
        perror("Error getting GPIO line 2");
        gpiod_line_release(gpio_line_1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line 1 as output
    if (gpiod_line_request_output(gpio_line_1, "gpio_output", 0) < 0) {
        perror("Error requesting GPIO line 1 as output");
        gpiod_line_release(gpio_line_1);
        gpiod_line_release(gpio_line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line 2 as output
    if (gpiod_line_request_output(gpio_line_2, "gpio_output", 0) < 0) {
        perror("Error requesting GPIO line 2 as output");
        gpiod_line_release(gpio_line_1);
        gpiod_line_release(gpio_line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO line 1 HIGH
        if (gpiod_line_set_value(gpio_line_1, 1) < 0) {
            perror("Error setting GPIO line 1 HIGH");
            break;
        }
        printf("GPIO %d HIGH\n", GPIO_PIN_1);
        sleep(1);

        // Set GPIO line 1 LOW
        if (gpiod_line_set_value(gpio_line_1, 0) < 0) {
            perror("Error setting GPIO line 1 LOW");
            break;
        }
        printf("GPIO %d LOW\n", GPIO_PIN_1);
