#include <stdio.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096

int i2c_fd;

void signal_handler(int sig);
int16_t read_ads1115();

int main() {
    signal(SIGINT, signal_handler);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave.");
        close(i2c_fd);
        return 1;
    }

    printf("ADS1115 reader. Press Ctrl+C to exit.\n");

    while (1) {
        int16_t reading = read_ads1115();
        if (reading != -1) {
            printf("Reading: %d\n", reading);
        } else {
            fprintf(stderr, "Error reading ADC value.\n");
        }
        usleep(100000); // 0.1 seconds
    }

    return 0;
}

void signal_handler(int sig) {
    printf("\nExiting...\n");
    close(i2c_fd);
    exit(0);
}

int16_t read_ads1115() {
    uint8_t config[3];
    uint8_t buf[2];

    // Configure for single-ended A0, 4.096V range, single conversion
    config[0] = CONFIG_REG;
    config[1] = 0x40; // OS=1, MUX=000 (A0), PGA=000 (4.096V)
    config[2] = 0x83; // MODE=1, DR=100 (128 SPS), COMP_MODE=Traditional, COMP_POL=Active low, COMP_LAT=Non-latching, COMP_QUE=Disable comparator

    if (write(i2c_fd, config, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }

    usleep(10000); // Wait for conversion (at least 8ms for 128 SPS)

    // Read conversion register
    if (write(i2c_fd, (uint8_t[]){CONVERSION_REG}, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    int16_t reading = (buf[0] << 8) | buf[1];
    return reading;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIOCHIP "gpiochip0"
#define GPIO17 17
#define GPIO18 18

static struct gpiod_chip *chip;
static struct gpiod_line *gpio17_line;
static struct gpiod_line *gpio18_line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

int main() {
    int ret;
    unsigned int value;

    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO 17 line
    gpio17_line = gpiod_chip_get_line(chip, GPIO17);
    if (!gpio17_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO17, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get GPIO 18 line
    gpio18_line = gpiod_chip_get_line(chip, GPIO18);
    if (!gpio18_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO18, strerror(errno));
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 17 as output
    ret = gpiod_line_request_output(gpio17_line, "gpio-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO17, strerror(errno));
        gpiod_line_release(gpio18_line);
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 18 as output
    ret = gpiod_line_request_output(gpio18_line, "gpio-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO18, strerror(errno));
        gpiod_line_release(gpio17_line);
        gpiod_line_release(gpio18_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d and GPIO %d set to output mode.  Reporting state.\n", GPIO17, GPIO18);

    while (keep_running) {
        // Read the state of GPIO 17
        ret = gpiod_line_get_value(gpio17_line);
        if (ret < 0) {
            fprintf(stderr, "Error getting GPIO line %d value: %s\n", GPIO17, strerror(errno));
            break; // Exit loop on error
        }
        value = ret;

        // Read the state of GPIO 18
        ret = gpiod_line_get_value(gpio18_line);
        if (ret < 0) {
            fprintf(stderr, "Error getting GPIO line %d value: %s\n", GPIO18, strerror(errno));
            break; // Exit loop on error
        }
        value |= (ret << 1); // Shift and OR to combine values

        printf("GPIO17: %d, GPIO18: %d, Combined: %d\n", gpiod_line_get_value(gpio17_line), gpiod_line_get_value(gpio18_line), value);

        sleep(1);
    }

    // Release GPIO lines and chip
    gpiod_line_release(gpio17_line);
    gpiod_line_release(gpio18_line);
    gpiod_chip_close(chip);

    printf("GPIO lines released. Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int gpio_status;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO 18 as output */
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    /* Set PWM frequency to 1000 Hz */
    gpioSetPWMfrequency(GPIO_PIN, 1000);

    /* Set PWM range (duty cycle resolution) */
    gpioSetPWMrange(GPIO_PIN, 1000);

    /* Main loop */
    while (!terminate) {
        /* Set PWM duty cycle (0-1000) */
        gpioPWM(GPIO_PIN, 500); // 50% duty cycle

        /* Report the state to standard output */
        printf("PWM: 50%%\n");

        /* Wait for 0.5 seconds */
        gpioDelay(500000); // 0.5 seconds in microseconds
    }

    /* Stop PWM output */
    gpioPWM(GPIO_PIN, 0);

    /* Terminate pigpio library */
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int gpio_status;
    double start_time, end_time, pulse_duration;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    printf("HC-SR04 sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Trigger the sensor
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10); // 10 us trigger pulse
        gpioWrite(TRIGGER_PIN, 0);

        // Measure the echo pulse duration
        start_time = time_time();
        while (gpioRead(ECHO_PIN) == 0) {
            if (time_time() - start_time > 0.1) { // Timeout after 0.1 seconds
                fprintf(stderr, "Timeout waiting for echo start\n");
                continue; // Retry
            }
        }
        start_time = time_time();

        while (gpioRead(ECHO_PIN) == 1) {
            if (time_time() - start_time > 0.1) { // Timeout after 0.1 seconds
                fprintf(stderr, "Timeout waiting for echo end\n");
                continue; // Retry
            }
        }
        end_time = time_time();

        pulse_duration = end_time - start_time;

        // Calculate distance in centimeters (speed of sound: 343 m/s)
        // distance = (pulse_duration * 34300) / 2
        double distance = pulse_duration * 34300 / 2.0;

        printf("Distance: %.2f cm\n", distance);

        gpioDelay(60000); // Wait 60 seconds
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0040  // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0080   // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// I2C device file
#define I2C_DEV "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a 16-bit value to the I2C device
int write_i2c_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;      // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the I2C device
int read_i2c_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    printf("ADS1115 reader started. Press Ctrl+C to exit.\n");

    while (1) {
        // Configure ADS1115 for single-ended AIN0, +/-4.096V, single-shot mode, 128 SPS
        uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE;

        // Write configuration to ADS1115
        if (write_i2c_word(i2c_fd, ADS1115_REG_CONFIG, config) < 0) {
            fprintf(stderr, "Error writing to config register.\n");
            close(i2c_fd);
            return 1;
        }

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        usleep(10000); // 10ms

        // Read conversion result
        uint16_t conversion;
        if (read_i2c_word(i2c_fd, ADS1115_REG_CONVERT, &conversion) < 0) {
            fprintf(stderr, "Error reading conversion result.\n");
            close(i2c_fd);
            return 1;
        }

        // Validate reading
        if (conversion < -4096 || conversion > 4096) {
            fprintf(stderr, "Invalid reading: %d\n", conversion);
            close(i2c_fd);
            return 1;
        }

        // Print reading to standard output
        printf("Reading: %d\n", conversion);

        // Wait 5 seconds
        sleep(5);
    }

    // This point should not be reached due to the signal handler
    close(i2c_fd);
    return 0;
}

