#include <stdio.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00

int main() {
    int fd;
    int i2c_addr = ADS1115_ADDR;

    // Open I2C bus
    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(fd, I2C_SLAVE, i2c_addr) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Configure ADS1115 for single-ended channel 0, 4.096V range, single-shot mode
    uint8_t config[3];
    config[0] = CONFIG_REG;
    config[1] = 0x43; // MSB: 01000011 (Single-ended AIN0, +/-4.096V, Single-shot)
    config[2] = 0x83; // LSB: 10000011 (128 SPS, Disable comparator)

    if (write(fd, config, 3) != 3) {
        perror("Failed to write to I2C device");
        close(fd);
        return 1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read conversion result
    uint8_t reg = CONVERSION_REG;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        close(fd);
        return 1;
    }

    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("Failed to read from I2C device");
        close(fd);
        return 1;
    }

    int16_t raw = (data[0] << 8) | data[1];
    double voltage = raw * 4.096 / 32768.0;

    printf("ADC Value: %d, Voltage: %.3f V\n", raw, voltage);

    close(fd);
    return 0;
}

