#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    int ret;
    int value;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d output control started. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (keep_running) {
        // Read current value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break; // Exit loop on error
        }

        // Print current state
        printf("GPIO %d is %s\n", GPIO_PIN, (value == 0) ? "LOW" : "HIGH");

        // Toggle value
        value = (value == 0) ? 1 : 0;
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break; // Exit loop on error
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Release GPIO line
    if (line) {
        gpiod_line_release(line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("GPIO %d output control stopped.\n", GPIO_PIN);

    return EXIT_SUCCESS;
}

