    gpio17_line = gpiod_chip_get_line(chip, GPIO_17);
    gpio22_line = gpiod_chip_get_line(chip, GPIO_22);
    gpio27_line = gpiod_chip_get_line(chip, GPIO_27);

    if (!gpio4_line || !gpio17_line || !gpio22_line || !gpio27_line) {
        perror("Error getting GPIO line");
        // Release previously acquired lines
        if(gpio4_line) gpiod_line_release(gpio4_line);
        if(gpio17_line) gpiod_line_release(gpio17_line);
        if(gpio22_line) gpiod_line_release(gpio22_line);
        if(gpio27_line) gpiod_line_release(gpio27_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio4_line, &config, 0) < 0) {
        perror("Error requesting GPIO 4 for output");
        goto cleanup;
    }
    if (gpiod_line_request(gpio17_line, &config, 0) < 0) {
        perror("Error requesting GPIO 17 for output");
