#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define TEMP_MEASURE_HOLD 0xE3
#define HUMID_MEASURE_HOLD 0xE5

int i2c_fd;
volatile sig_atomic_t stop_flag = 0;

void signal_handler(int sig) {
    stop_flag = 1;
}

int read_measurement(unsigned char command) {
    if (write(i2c_fd, &command, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    usleep(100000); // Wait for measurement (at least 85ms)

    unsigned char buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    unsigned int raw = (buf[0] << 8) | buf[1];
    return raw;
}

float convert_temperature(unsigned int raw) {
    return ((175.72 * raw) / 65536.0) - 46.85;
}

float convert_humidity(unsigned int raw) {
    return ((125.0 * raw) / 65536.0) - 6.0;
}

int main() {
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!stop_flag) {
        unsigned int raw_temp = read_measurement(TEMP_MEASURE_HOLD);
        unsigned int raw_humidity = read_measurement(HUMID_MEASURE_HOLD);

        if (raw_temp == -1 || raw_humidity == -1) {
            fprintf(stderr, "Error reading sensor data. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        float temperature = convert_temperature(raw_temp);
        float humidity = convert_humidity(raw_humidity);

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

        printf("%s - Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);

        sleep(5);
    }

    close(i2c_fd);
    printf("Program terminated.\n");
    return 0;
}

