#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096

int i2c_fd;
volatile sig_atomic_t stop_flag = 0;

void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully.\n", sig);
    stop_flag = 1;
}

int read_ads1115(int fd, int address) {
    unsigned char config[3];
    int16_t raw_value;
    float voltage;

    // Configure ADS1115 for single-ended channel 0, 4.096V range, single-shot mode
    config[0] = CONFIG_REG;
    config[1] = 0x40; // OS=1, MUX=000 (AIN0)
    config[2] = 0xC3; // PGA=011 (±4.096V), MODE=1 (Single-shot)

    if (write(fd, config, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 4.096V range)
    usleep(10000); // 10ms

    // Read conversion register
    unsigned char read_buffer[2];
    if (write(fd, (unsigned char[]){CONVERSION_REG}, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(fd, read_buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    raw_value = (read_buffer[0] << 8) | read_buffer[1];

    // Calculate voltage
    voltage = (raw_value * REF_VOLTAGE) / 32768.0;

    return raw_value;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 1;  // 1 second
    sleep_time.tv_nsec = 0; // 0 nanoseconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    printf("ADS1115 reader. Press Ctrl+C to exit.\n");

    while (!stop_flag) {
        int raw_value = read_ads1115(i2c_fd, ADS1115_ADDR);
        if (raw_value >= 0) {
            float voltage = (raw_value * REF_VOLTAGE) / 32768.0;
            printf("Raw: %d, Voltage: %.3f V\n", raw_value, voltage);
        } else {
            fprintf(stderr, "Failed to read ADS1115 value.\n");
        }

        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep failed");
        }
    }

    // Close I2C bus
    close(i2c_fd);

    printf("Exited cleanly.\n");
    return 0;
}

