#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *trigger_line;
struct gpiod_line *echo_line;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully.\n", sig);

    // Release GPIO lines
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to trigger the HC-SR04 sensor
void trigger_sensor(struct gpiod_line *trigger_line)
{
    int ret;

    // Set trigger pin HIGH for 10 microseconds
    ret = gpiod_line_set_value(trigger_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting trigger HIGH: %s\n", gpiod_line_name(trigger_line));
        exit(1);
    }
    usleep(10); // 10 microseconds

    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting trigger LOW: %s\n", gpiod_line_name(trigger_line));
        exit(1);
    }
}

// Function to measure the echo pulse width
long measure_pulse_width(struct gpiod_line *echo_line)
{
    struct timespec start, end;
    long pulse_width;
    int ret;

    // Wait for echo pin to go HIGH
    while (1) {
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            fprintf(stderr, "Error getting echo value: %s\n", gpiod_line_name(echo_line));
            return -1; // Indicate error
        }
        if (ret == 1) break; // Echo pin is HIGH
        usleep(1); // Small delay to avoid busy-waiting
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for echo pin to go LOW
    while (1) {
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            fprintf(stderr, "Error getting echo value: %s\n", gpiod_line_name(echo_line));
            return -1; // Indicate error
        }
        if (ret == 0) break; // Echo pin is LOW
        usleep(1); // Small delay to avoid busy-waiting
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate pulse width in nanoseconds
    pulse_width = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);

    return pulse_width;
}

int main()
{
    int ret;
    long pulse_width;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", CHIP_NAME);
        return 1;
    }

    // Get GPIO lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Error getting trigger line: %d\n", TRIGGER_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Error getting echo line: %d\n", ECHO_PIN);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output and input, respectively
    ret = gpiod_line_request_output(trigger_line, "hc-sr04_trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting trigger line as output: %s\n", gpiod_line_name(trigger_line));
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(echo_line, "hc-sr04_echo");
    if (ret < 0) {
        fprintf(stderr, "Error requesting echo line as input: %s\n", gpiod_line_name(echo_line));
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Trigger the sensor
        trigger_sensor(trigger_line);

        // Measure the pulse width
        pulse_width = measure_pulse_width(echo_line);

        // Report the pulse width
        if (pulse_width >= 0) {
            printf("Pulse width: %ld ns\n", pulse_width);
        } else {
            fprintf(stderr, "Error measuring pulse width.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

