#include <errno.h>

// Define the GPIO pins to be used
#define GPIO_PIN_1 23
#define GPIO_PIN_2 24
#define GPIO_PIN_3 25

// Define the chip name (adjust if necessary)
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *gpio_line_1, *gpio_line_2, *gpio_line_3;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully...\n", sig);

    // Release GPIO lines
    if (gpio_line_1) {
        gpiod_line_release(gpio_line_1);
    }
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }
    if (gpio_line_3) {
        gpiod_line_release(gpio_line_3);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int ret;
    unsigned int value;

    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO lines
    gpio_line_1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    gpio_line_2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    gpio_line_3 = gpiod_chip_get_line(chip, GPIO_PIN_3);

    if (!gpio_line_1 || !gpio_line_2 || !gpio_line_3) {
        perror("Error getting GPIO line");
        // Release any previously obtained lines before exiting
        if(gpio_line_1) gpiod_line_release(gpio_line_1);
        if(gpio_line_2) gpiod_line_release(gpio_line_2);
        if(gpio_line_3) gpiod_line_release(gpio_line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines for output
    ret = gpiod_line_request_output(gpio_line_1, "gpio_output", 0);
    ret |= gpiod_line_request_output(gpio_line_2, "gpio_output", 0);
    ret |= gpiod_line_request_output(gpio_line_3, "gpio_output", 0);

    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        // Release any previously obtained lines before exiting
        if(gpio_line_1) gpiod_line_release(gpio_line_1);
        if(gpio_line_2) gpiod_line_release(gpio_line_2);
        if(gpio_line_3) gpiod_line_release(gpio_line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set the GPIO values
        value = (1 << GPIO_PIN_1) | (1 << GPIO_PIN_2) | (1 << GPIO_PIN_3);
        ret = gpiod_line_set_value(gpio_line_1, value & (1 << GPIO_PIN_1));
        ret |= gpiod_line_set_value(gpio_line_2, value & (1 << GPIO_PIN_2));
        ret |= gpiod_line_set_value(gpio_line_3, value & (1 << GPIO_PIN_3));

        if (ret < 0) {
            perror("Error setting GPIO value");
            // Release GPIO lines before exiting
            if(gpio_line_1) gpiod_line_release(gpio_line_1);
            if(gpio_line_2) gpiod_line_release(gpio_line_2);
            if(gpio_line_3) gpiod_line_release(gpio_line_3);
            gpiod_chip_close(chip);
            return 1;
        }

        // Print the current state
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
               GPIO_PIN_1, (1 << GPIO_PIN_1) & value,
               GPIO_PIN_2, (1 << GPIO_PIN_2) & value,
               GPIO_PIN_3, (1 << GPIO_PIN_3) & value);

        // Wait for 0.1 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

