#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nExiting program...\n");
}

int main() {
    int gpio_status;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_PIN_1, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_2, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Read GPIO states
        gpio_status = gpioRead(GPIO_PIN_1);
        if (gpio_status < 0) {
            fprintf(stderr, "Error reading GPIO %d: %d\n", GPIO_PIN_1, gpio_status);
            gpio_status = -1; // Indicate error
        }

        gpio_status = gpioRead(GPIO_PIN_2);
        if (gpio_status < 0) {
            fprintf(stderr, "Error reading GPIO %d: %d\n", GPIO_PIN_2, gpio_status);
            gpio_status = -1; // Indicate error
        }

        // Validate GPIO readings
        if (gpio_status != 0 && gpio_status != 1) {
            fprintf(stderr, "Invalid GPIO reading: %d\n", gpio_status);
            gpio_status = -1; // Indicate invalid reading
        }

        // Print GPIO states
        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, gpio_status, GPIO_PIN_2, gpio_status);

        // Delay for 5 seconds
        sleep(5);
    }

    // Clean up GPIO pins before exiting
    gpioWrite(GPIO_PIN_1, 0); // Set to LOW
    gpioWrite(GPIO_PIN_2, 0); // Set to LOW
    gpioTerminate();

    return 0;
}

