// Define the GPIO pins to be used
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

// Define the chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *gpio4_line, *gpio17_line, *gpio22_line, *gpio27_line;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully.\n", sig);

    // Release GPIO lines
    if (gpio4_line) {
        gpiod_line_release(gpio4_line);
    }
    if (gpio17_line) {
        gpiod_line_release(gpio17_line);
    }
    if (gpio22_line) {
        gpiod_line_release(gpio22_line);
    }
    if (gpio27_line) {
        gpiod_line_release(gpio27_line);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    gpio4_line = gpiod_chip_get_line(chip, GPIO_4);
    gpio17_line = gpiod_chip_get_line(chip, GPIO_17);
    gpio22_line = gpiod_chip_get_line(chip, GPIO_22);
    gpio27_line = gpiod_chip_get_line(chip, GPIO_27);

    if (!gpio4_line || !gpio17_line || !gpio22_line || !gpio27_line) {
        perror("Error getting GPIO line");
        // Release previously acquired lines
        if(gpio4_line) gpiod_line_release(gpio4_line);
        if(gpio17_line) gpiod_line_release(gpio17_line);
        if(gpio22_line) gpiod_line_release(gpio22_line);
        if(gpio27_line) gpiod_line_release(gpio27_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio4_line, &config, 0) < 0) {
        perror("Error requesting GPIO 4 for output");
        goto cleanup;
    }
    if (gpiod_line_request(gpio17_line, &config, 0) < 0) {
        perror("Error requesting GPIO 17 for output");
        goto cleanup;
    }
    if (gpiod_line_request(gpio22_line, &config, 0) < 0) {
        perror("Error requesting GPIO 22 for output");
        goto cleanup;
    }
    if (gpiod_line_request(gpio27_line, &config, 0) < 0) {
        perror("Error requesting GPIO 27 for output");
        goto cleanup;
    }

    // Main loop
    while (1) {
        // Set GPIO states
        int state = !((1 << GPIO_4) | (1 << GPIO_17) | (1 << GPIO_22) | (1 << GPIO_27));
        if (gpiod_line_set_value(gpio4_line, state) < 0) {
            perror("Error setting GPIO 4 value");
            goto cleanup;
        }
        if (gpiod_line_set_value(gpio17_line, state) < 0) {
            perror("Error setting GPIO 17 value");
            goto cleanup;
        }
        if (gpiod_line_set_value(gpio22_line, state) < 0) {
            perror("Error setting GPIO 22 value");
            goto cleanup;
        }
        if (gpiod_line_set_value(gpio27_line, state) < 0) {
            perror("Error setting GPIO 27 value");
            goto cleanup;
        }

        // Print the current state
        printf("GPIO 4: %d, GPIO 17: %d, GPIO 22: %d, GPIO 27: %d\n",
               gpiod_line_get_value(gpio4_line),
               gpiod_line_get_value(gpio17_line),
               gpiod_line_get_value(gpio22_line),
               gpiod_line_get_value(gpio27_line));

        // Wait for 1 second
        sleep(1);
    }

cleanup:
    // Release GPIO lines
    if (gpio4_line) {
        gpiod_line_release(gpio4_line);
    }
    if (gpio17_line) {
        gpiod_line_release(gpio17_line);
    }
    if (gpio22_line) {
        gpiod_line_release(gpio22_line);
    }
    if (gpio27_line) {
        gpiod_line_release(gpio27_line);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 1;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    int ret;
    int value;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d output control started. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (keep_running) {
        // Read current value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        // Print current state
        printf("GPIO %d is %s\n", GPIO_PIN, (value == 0) ? "LOW" : "HIGH");

        // Toggle value
        ret = gpiod_line_set_value(line, !value);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        // Wait 0.5 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    if (line) {
        gpiod_line_release(line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("GPIO %d output control stopped.\n", GPIO_PIN);

    return (keep_running) ? EXIT_SUCCESS : EXIT_FAILURE;
}

