#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>

#define DHT11_GPIO 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht11(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_counts[80];
    int i, j;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30);
    gpioSetMode(gpio, PI_INPUT);

    for (i = 0; i < 80; i++) {
        int count = 0;
        while (gpioRead(gpio) == (i % 2 == 0)) {
            count++;
            gpioDelay(1);
            if (count > 200) return -1; // Timeout
        }
        pulse_counts[i] = count;
    }

    for (i = 0; i < 40; i++) {
        int index = i + 40;
        if (pulse_counts[index] > pulse_counts[index - 1] && pulse_counts[index] > pulse_counts[index - 2]) {
            data[bit_count / 8] <<= 1;
            if (pulse_counts[index + 1] > pulse_counts[index]) {
                data[bit_count / 8] |= 1;
            }
            bit_count++;
        }
    }

    if (bit_count != 40) {
        return -2; // Not enough data
    }

    if ((data[0] + data[1] + data[2] + data[3]) & 0xFF != data[4]) {
        return -3; // Checksum failure
    }

    *humidity = (float)(((data[0] << 8) + data[1])) / 10.0;
    *temperature = (float)(((data[2] << 8) + data[3])) / 10.0;
    if (*temperature > 125) {
        *temperature = *temperature - 256;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    float temperature, humidity;
    int result;

    while (!terminate) {
        result = read_dht11(DHT11_GPIO, &temperature, &humidity);
        if (result == 0) {
            printf("Temperature: %.1f°C, Humidity: %.1f%%\n", temperature, humidity);
        } else {
            fprintf(stderr, "DHT11 read failed with error code: %d\n", result);
        }
        sleep(5);
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

