#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_2 2
#define GPIO_3 3
#define GPIO_18 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int gpio_status;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO modes */
    gpioSetMode(GPIO_2, PI_OUTPUT);
    gpioSetMode(GPIO_3, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);

    /* Set PWM frequency (adjust as needed) */
    gpioSetPWMfrequency(GPIO_2, 1000); // 1 kHz
    gpioSetPWMfrequency(GPIO_3, 1000);
    gpioSetPWMfrequency(GPIO_18, 1000);

    /* Set PWM range (adjust as needed) */
    gpioSetPWMrange(GPIO_2, 255);
    gpioSetPWMrange(GPIO_3, 255);
    gpioSetPWMrange(GPIO_18, 255);

    /* Register signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    printf("PWM output on GPIO 2, 3, 18 (BCM numbering). Press Ctrl+C to exit.\n");

    while (!terminate) {
        /* Set PWM duty cycle (adjust as needed) */
        gpioPWM(GPIO_2, 128); // 50% duty cycle
        gpioPWM(GPIO_3, 191); // 75% duty cycle
        gpioPWM(GPIO_18, 255); // 100% duty cycle

        /* Report the state */
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n", GPIO_2, gpioRead(GPIO_2), GPIO_3, gpioRead(GPIO_3), GPIO_18, gpioRead(GPIO_18));

        /* Wait for 0.15 seconds */
        gpioDelay(150000); // 150 ms
    }

    /* Stop PWM output */
    gpioPWM(GPIO_2, 0);
    gpioPWM(GPIO_3, 0);
    gpioPWM(GPIO_18, 0);

    /* Terminate pigpio library */
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

