    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int ret;
    struct timespec sleep_time = {0, 100000000}; // 0.1 seconds
    int state = 0;

    // Register signal handler for SIGINT (Ctrl+C)
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

