#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the GPIO pins to control
#define GPIO_PINS {2, 3, 4, 5, 6, 7, 8, 9, 17}

// Structure to hold GPIO chip and line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[9]; // Assuming a maximum of 9 GPIO pins
} gpio_state_t;

// Global variable to store the GPIO state
gpio_state_t gpio_state;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < 9; i++) {
        if (gpio_state.lines[i]) {
            gpiod_line_release(gpio_state.lines[i]);
        }
    }

    // Close the GPIO chip
    if (gpio_state.chip) {
        gpiod_chip_close(gpio_state.chip);
    }

    exit(0);
}

// Function to set the state of a GPIO pin
int set_gpio_state(gpio_state_t *gpio_state, int pin, int value) {
    int line_index = -1;
    for (int i = 0; i < 9; i++) {
        if (gpio_state->lines[i] && gpiod_line_get_number(gpio_state->lines[i]) == pin) {
            line_index = i;
            break;
        }
    }

    if (line_index == -1) {
        fprintf(stderr, "Error: GPIO pin %d not found in GPIO state.\n", pin);
        return -1;
    }

    int ret = gpiod_line_set_value(gpio_state->lines[line_index], value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d to %d: %s\n", pin, value, strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    gpio_state.chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_state.chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the GPIO lines
    for (int i = 0; i < 9; i++) {
        int pin = GPIO_PINS[i];
        gpio_state.lines[i] = gpiod_chip_get_line(gpio_state.chip, pin);
        if (!gpio_state.lines[i]) {
            fprintf(stderr, "Error getting GPIO %d: %s\n", pin, strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(gpio_state.lines[j]);
            }
            gpiod_chip_close(gpio_state.chip);
            return 1;
        }

        // Request the line for output
        int ret = gpiod_line_request_output(gpio_state.lines[i], "gpio_output", 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO %d as output: %s\n", pin, strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(gpio_state.lines[j]);
            }
            gpiod_chip_close(gpio_state.chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        for (int i = 0; i < 9; i++) {
            int pin = GPIO_PINS[i];
            // Toggle the state of the GPIO pin
            int new_value = (i % 2 == 0) ? 1 : 0; // Even index -> 1, odd index -> 0
            if (set_gpio_state(&gpio_state, pin, new_value) != 0) {
                fprintf(stderr, "Error setting GPIO %d, exiting.\n", pin);
                // Release previously acquired lines
                for (int j = 0; j < 9; j++) {
                    gpiod_line_release(gpio_state.lines[j]);
                }
                gpiod_chip_close(gpio_state.chip);
                return 1;
            }
        }

        // Wait for 0.05 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50000000; // 50 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

