#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define OPT3001_ADDR 0x44
#define RESULT_REG 0x00

int main() {
    int fd;
    char filename[20];
    uint8_t buf[2];
    int16_t raw_result;
    float voltage;
    float temperature;
    float pressure;

    snprintf(filename, 19, "/dev/i2c-1");
    fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave.");
        close(fd);
        return 1;
    }

    // Read result register
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read result register");
        close(fd);
        return 1;
    }

    raw_result = (buf[0] << 8) | buf[1];

    // Extract data
    voltage = ((raw_result >> 3) * 0.0625);
    temperature = ((raw_result & 0x07) * 0.25);
    pressure = ((raw_result >> 2) * 0.1);

    printf("Voltage: %.2f V, Temperature: %.2f C, Pressure: %.2f Pa\n", voltage, temperature, pressure);

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    int ret;
    int value;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Read current value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        // Print the state
        printf("GPIO %d is %s\n", GPIO_PIN, (value == 0) ? "LOW" : "HIGH");

        // Toggle the state
        ret = gpiod_line_set_value(line, !value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        // Wait 0.5 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

