#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    int value;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(line, "gpio-output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d output control\n", GPIO_PIN);

    while (keep_running) {
        // Read GPIO value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        // Validate GPIO value (0 or 1)
        if (value != 0 && value != 1) {
            fprintf(stderr, "Invalid GPIO value: %d\n", value);
            continue; // Skip printing invalid value
        }

        // Print GPIO value
        printf("GPIO %d: %d\n", GPIO_PIN, value);

        // Delay
        struct timespec delay = {0, 100000000}; // 100 milliseconds
        nanosleep(&delay, NULL);
    }

    // Release GPIO line
    if (gpiod_line_release(line) < 0) {
        fprintf(stderr, "Error releasing GPIO line: %s\n", strerror(errno));
    }

    // Close GPIO chip
    if (gpiod_chip_close(chip) < 0) {
        fprintf(stderr, "Error closing GPIO chip: %s\n", strerror(errno));
    }

    printf("GPIO %d output control finished\n", GPIO_PIN);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_A 2
#define GPIO_B 3

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCtrl+C detected. Exiting gracefully...\n");
}

// Function to read the state of a GPIO pin
int read_gpio(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to validate the GPIO state
int validate_gpio_state(int gpio, int state) {
    return (state == 0 || state == 1);
}

// Function to report the state of both GPIOs
void report_state(int gpio_a_state, int gpio_b_state) {
    printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_A, gpio_a_state, GPIO_B, gpio_b_state);
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(GPIO_A, PI_INPUT);
    gpioSetMode(GPIO_B, PI_INPUT);

    printf("Reading GPIO %d and %d. Press Ctrl+C to exit.\n", GPIO_A, GPIO_B);

    // Main loop
    while (program_running) {
        // Read the state of GPIO A
        int gpio_a_state = read_gpio(GPIO_A);
        if (gpio_a_state == -1) {
            fprintf(stderr, "Error reading GPIO %d. Exiting.\n", GPIO_A);
            break;
        }

        // Read the state of GPIO B
        int gpio_b_state = read_gpio(GPIO_B);
        if (gpio_b_state == -1) {
            fprintf(stderr, "Error reading GPIO %d. Exiting.\n", GPIO_B);
            break;
        }

        // Validate the states
        if (!validate_gpio_state(GPIO_A, gpio_a_state)) {
            fprintf(stderr, "Invalid state for GPIO %d: %d. Exiting.\n", GPIO_A, gpio_a_state);
            break;
        }
        if (!validate_gpio_state(GPIO_B, gpio_b_state)) {
            fprintf(stderr, "Invalid state for GPIO %d: %d. Exiting.\n", GPIO_B, gpio_b_state);
            break;
        }

        // Report the state
        report_state(gpio_a_state, gpio_b_state);

        // Delay for 100 milliseconds
        gpioDelay(100000);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

