        gpiod_line_release(gpio23_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(gpio23_line, "gpio-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n", GPIO23, strerror(errno));
        gpiod_line_release(gpio24_line);
        gpiod_line_release(gpio23_line);
        gpiod_chip_close(chip);
        return 1;
