        gpiod_line_release(gpio23_line);
        gpiod_line_release(gpio24_line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d and GPIO %d set to output mode (initial value: 0)\n", GPIO23, GPIO24);

    while (keep_running) {
        value = (value + 1) & 1; // Toggle the value

        ret = gpiod_line_set_value(gpio23_line, value);
