        ret = gpiod_line_set_value(gpio17_line, !gpiod_line_get_value(gpio17_line));
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO17, strerror(errno));
            break; // Exit loop on error
        }

        // Toggle GPIO 18
        ret = gpiod_line_set_value(gpio18_line, !gpiod_line_get_value(gpio18_line));
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO18, strerror(errno));
            break; // Exit loop on error
        }

        // Wait 0.5 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (gpio17_line) {
        gpiod_line_release(gpio17_line);
    }
    if (gpio18_line) {
        gpiod_line_release(gpio18_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B9600

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int setup_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 9600 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = setup_uart(UART_DEVICE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    printf("UART initialized on %s at %d baud.\n", UART_DEVICE, BAUD_RATE);

    char buffer[256];
    ssize_t bytes_read;
    struct timespec start, end;
    double elapsed;

    while (program_running) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);

        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s\n", buffer);
        } else if (bytes_read == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // No data available, try again
                continue;
            } else {
                perror("Error reading from UART");
                break;
            }
        } else {
            // UART closed or error
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000.0;
        //printf("Time taken: %.6f seconds\n", elapsed);

        usleep(100000); // Sleep for 100ms
    }

    if (uart_fd != -1) {
        close(uart_fd);
        printf("UART closed.\n");
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
