    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

int main() {
    int state;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 2 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read the current state
        state = gpioRead(GPIO_PIN);

        // Validate the state
        if (state != 0 && state != 1) {
            fprintf(stderr, "Error: Invalid GPIO state read: %d\n", state);
            continue; // Skip to the next iteration
        }

        // Apply the state
        gpioWrite(GPIO_PIN, state);

        // Report the state
        printf("GPIO %d: %s\n", GPIO_PIN, (state == 0) ? "LOW" : "HIGH");

        // Wait for 60 seconds
        sleep(60);
    }

    // Cleanup
    gpioWrite(GPIO_PIN, 0); // Set to LOW before exiting
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

