        if(gpio_line_3) gpiod_line_release(gpio_line_3);
        if(gpio_line_4) gpiod_line_release(gpio_line_4);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines for output
    ret = gpiod_line_request_output(gpio_line_1, "gpio_output", 0);
    ret |= gpiod_line_request_output(gpio_line_2, "gpio_output", 0);
    ret |= gpiod_line_request_output(gpio_line_3, "gpio_output", 0);
    ret |= gpiod_line_request_output(gpio_line_4, "gpio_output", 0);

    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        // Release any previously obtained lines
        if(gpio_line_1) gpiod_line_release(gpio_line_1);
        if(gpio_line_2) gpiod_line_release(gpio_line_2);
        if(gpio_line_3) gpiod_line_release(gpio_line_3);
        if(gpio_line_4) gpiod_line_release(gpio_line_4);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the current state of the GPIO lines
        value = gpiod_line_get_value(gpio_line_1);
        value |= (gpiod_line_get_value(gpio_line_2) << 1);
        value |= (gpiod_line_get_value(gpio_line_3) << 2);
        value |= (gpiod_line_get_value(gpio_line_4) << 3);

        // Print the current state
        printf("GPIO state: %u\n", value);

        // Wait for 0.1 seconds
        usleep(100000); // 100 ms = 0.1 seconds
    }

    return 0;
}

