#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_2 2
#define GPIO_3 3

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int gpio2_state, gpio3_state;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO 2 and 3 as outputs */
    gpioSetMode(GPIO_2, PI_OUTPUT);
    gpioSetMode(GPIO_3, PI_OUTPUT);

    /* Register signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    printf("GPIO 2 and 3 control program. Press Ctrl+C to exit.\n");

    while (!terminate) {
        /* Read the state of GPIO 2 and 3 */
        gpio2_state = gpioRead(GPIO_2);
        gpio3_state = gpioRead(GPIO_3);

        /* Validate the readings */
        if (gpio2_state != 0 && gpio2_state != 1) {
            fprintf(stderr, "Error: Invalid reading from GPIO %d: %d\n", GPIO_2, gpio2_state);
        }
        if (gpio3_state != 0 && gpio3_state != 1) {
            fprintf(stderr, "Error: Invalid reading from GPIO %d: %d\n", GPIO_3, gpio3_state);
        }

        /* Print the state of GPIO 2 and 3 */
        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_2, gpio2_state, GPIO_3, gpio3_state);

        /* Wait for 0.1 seconds */
        gpioDelay(100000); // 100 ms
    }

    /* Set GPIO 2 and 3 to input mode (safer) */
    gpioSetMode(GPIO_2, PI_INPUT);
    gpioSetMode(GPIO_3, PI_INPUT);

    /* Terminate pigpio library */
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

