#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIOCHIP "gpiochip0"
#define GPIO4 4
#define GPIO17 17

static struct gpiod_chip *chip;
static struct gpiod_line *gpio4_line;
static struct gpiod_line *gpio17_line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

int main() {
    int ret;
    unsigned int value;

    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO4 line
    gpio4_line = gpiod_chip_get_line(chip, GPIO4);
    if (!gpio4_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO4, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get GPIO17 line
    gpio17_line = gpiod_chip_get_line(chip, GPIO17);
    if (!gpio17_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO17, strerror(errno));
        gpiod_line_release(gpio4_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO4 as output
    ret = gpiod_line_request_output(gpio4_line, "gpio4_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO4, strerror(errno));
        gpiod_line_release(gpio17_line);
        gpiod_line_release(gpio4_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO17 as output
    ret = gpiod_line_request_output(gpio17_line, "gpio17_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO17, strerror(errno));
        gpiod_line_release(gpio4_line);
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d and GPIO %d set to output mode.  Reporting state.\n", GPIO4, GPIO17);

    while (keep_running) {
        // Read GPIO4 state
        ret = gpiod_line_get_value(gpio4_line);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO4, strerror(errno));
            break; // Exit loop on error
        }
        value = ret;

        // Read GPIO17 state
        ret = gpiod_line_get_value(gpio17_line);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO17, strerror(errno));
            break; // Exit loop on error
        }
        value |= (ret << 1); // Shift and OR to combine values

        printf("GPIO4: %d, GPIO17: %d, Combined: %d\n", ret, ret, value);

        sleep(1);
    }

    // Release GPIO lines and chip
    gpiod_line_release(gpio4_line);
    gpiod_line_release(gpio17_line);
    gpiod_chip_close(chip);

    printf("GPIO lines and chip released. Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define the GPIO pin number (BCM numbering)
#define GPIO_PIN 2

// Define the chip name (e.g., "gpiochip0")
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO line and chip
struct gpiod_line *gpio_line = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully.\n", sig);

    // Release the GPIO line if it's held
    if (gpio_line)
    {
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "gpio-blink";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT; // Release the line

        if (gpiod_line_release_request(gpio_line, &config, 0) < 0)
        {
            perror("Error releasing GPIO line");
        }

        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }

    // Release the GPIO chip if it's held
    if (gpio_chip)
    {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }

    exit(0);
}

int main()
{
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 0.1 seconds

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!gpio_chip)
    {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line)
    {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request the GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio-blink";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0)
    {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Main loop: toggle the GPIO output three times
    for (int i = 0; i < 3; i++)
    {
        // Set the GPIO output to HIGH
        if (gpiod_line_set_value(gpio_line, 1) < 0)
        {
            perror("Error setting GPIO output HIGH");
            gpiod_line_release(gpio_line);
            gpiod_chip_close(gpio_chip);
            return 1;
        }
        printf("GPIO %d HIGH\n", GPIO_PIN);

        // Wait for 0.1 seconds
        nanosleep(&sleep_time, NULL);

        // Set the GPIO output to LOW
        if (gpiod_line_set_value(gpio_line, 0) < 0)
        {
            perror("Error setting GPIO output LOW");
            gpiod_line_release(gpio_line);
            gpiod_chip_close(gpio_chip);
            return 1;
        }
        printf("GPIO %d LOW\n", GPIO_PIN);

        // Wait for 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release the GPIO line
    struct gpiod_line_request_config release_config;
    memset(&release_config, 0, sizeof(release_config));
    release_config.consumer = "gpio-blink";
    release_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT; // Release the line

    if (gpiod_line_release_request(gpio_line, &release_config, 0) < 0)
    {
        perror("Error releasing GPIO line");
    }

    gpiod_line_release(gpio_line);
    gpio_line = NULL;

    // Close the GPIO chip
    gpiod_chip_close(gpio_chip);
    gpio_chip = NULL;

    printf("GPIO control complete.\n");

    return 0;
}

#include <stdio.h>
