#include <unistd.h>
#include <signal.h>

#define PWM_GPIO 4
#define PWM_FREQUENCY 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        // Toggle PWM duty cycle
        int duty_cycle = gpioGetPWMdutycycle(PWM_GPIO);
        if (duty_cycle == 0) {
            gpioPWM(PWM_GPIO, 128); // 50% duty cycle
        } else {
            gpioPWM(PWM_GPIO, 0);   // 0% duty cycle
        }

        printf("PWM: %d\n", duty_cycle);
