void signal_handler(int signum) {
    if (signum == SIGINT) {
        program_running = 0;
        printf("\nExiting program...\n");
    }
}

// Function to discover the DS18B20 device ID
int discover_device_id(char *device_id) {
    DIR *dir;
    struct dirent *ent;
    int found = 0;

    dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        perror("Error opening " W1_DEVICES_DIR);
        return -1;
    }

    while ((ent = readdir(dir)) != NULL) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            strncpy(device_id, ent->d_name, 20); // Copy the device ID
            device_id[19] = '\0'; // Ensure null termination
            found = 1;
            break;
        }
    }

    closedir(dir);
    if (!found) {
        fprintf(stderr, "Error: No DS18B20 device found.\n");
        return -1;
    }

    return 0;
}

// Function to read the temperature from the DS18B20
float read_temperature(const char *device_id) {
    char filepath[100];
    FILE *fp;
    char line[256];
    float temperature = -999.0; // Default invalid value

    snprintf(filepath, sizeof(filepath), "%s%s/%s", W1_DEVICES_DIR, device_id, W1_SLAVE_FILE);

    fp = fopen(filepath, "r");
    if (fp == NULL) {
        perror("Error opening " W1_SLAVE_FILE);
        return -999.0;
    }

    // Read the file line by line
    if (fgets(line, sizeof(line), fp) == NULL) {
        perror("Error reading line 1");
        fclose(fp);
        return -999.0;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        perror("Error reading line 2");
        fclose(fp);
        return -999.0;
    }

    fclose(fp);

    // Check for CRC error
    if (strstr(line, "YES") == NULL) {
        fprintf(stderr, "Error: CRC check failed.\n");
        return -999.0;
    }

    // Extract the temperature value
    char *temp_str = strstr(line, "t=");
    if (temp_str != NULL) {
        long temp_reading = strtol(temp_str + 2, NULL, 10);
        temperature = (float)temp_reading / 1000.0;
    } else {
        fprintf(stderr, "Error: Temperature value not found.\n");
        return -999.0;
    }

    return temperature;
}

// Function to validate the temperature reading
int validate_temperature(float temperature) {
    if (temperature < -40.0 || temperature > 85.0) {
        fprintf(stderr, "Error: Temperature reading out of range: %.2f\n", temperature);
        return 0; // Indicate invalid reading
    }
    return 1; // Indicate valid reading
}

