            perror("gpiod_line_set_value");
            break;
        }
        state = !state;
        printf("GPIO %d set to %d\n", GPIO_PIN, state);
        nanosleep(&sleep_time, NULL);
    }

    printf("Releasing GPIO %d...\n", GPIO_PIN);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Exiting.\n");
    return 0;
}

