static struct gpiod_line *gpio18_line;
static volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int ret;
    unsigned int value;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get GPIO 17 line
    gpio17_line = gpiod_chip_get_line(chip, GPIO17);
    if (!gpio17_line) {
        perror("gpiod_chip_get_line (GPIO17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get GPIO 18 line
    gpio18_line = gpiod_chip_get_line(chip, GPIO18);
    if (!gpio18_line) {
        perror("gpiod_chip_get_line (GPIO18)");
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 17 as output
    ret = gpiod_line_request_output(gpio17_line, "gpio17_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO17)");
        gpiod_line_release(gpio18_line);
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 18 as output
    ret = gpiod_line_request_output(gpio18_line, "gpio18_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO18)");
        gpiod_line_release(gpio17_line);
        gpiod_line_release(gpio18_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Read current state of GPIO 17
        ret = gpiod_line_get_value(gpio17_line);
        if (ret < 0) {
            perror("gpiod_line_get_value (GPIO17)");
            break; // Exit loop on error
        }
        value = ret;

        // Read current state of GPIO 18
        ret = gpiod_line_get_value(gpio18_line);
        if (ret < 0) {
            perror("gpiod_line_get_value (GPIO18)");
            break; // Exit loop on error
        }
        value |= (ret << 1); // Shift and OR to combine values

        // Print the combined value
        printf("GPIO17: %d, GPIO18: %d, Combined: %d\n",
               gpiod_line_get_value(gpio17_line),
               gpiod_line_get_value(gpio18_line),
