        ret = gpiod_line_set_value(gpio17_line, !gpiod_line_get_value(gpio17_line));
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO17)");
            break; // Exit loop on error
        }

        // Toggle GPIO 18
        ret = gpiod_line_set_value(gpio18_line, !gpiod_line_get_value(gpio18_line));
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO18)");
            break; // Exit loop on error
        }

        // Wait 500ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 500ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    gpiod_line_release(gpio17_line);
    gpiod_line_release(gpio18_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define DHT22_GPIO 17

static struct gpiod_chip *chip;
static struct gpiod_line *line;

int read_dht22(float *temperature, float *humidity) {
    int ret;
    unsigned int data[5] = {0, 0, 0, 0, 0};
    unsigned int bit_count = 0;
    unsigned int pulse_count = 0;
    unsigned int last_state = 0;
    unsigned int current_state = 0;
    unsigned int timeout = 0;

    // Request data
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting line low: %s\n", strerror(-ret));
        return -1;
    }
    usleep(1000); // > 1ms

    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting line high: %s\n", strerror(-ret));
        return -1;
    }
    usleep(30); // 20-40us

    // Read data
    for (int i = 0; i < 40; i++) {
        timeout = 0;
        while (1) {
            ret = gpiod_line_get_value(line);
            if (ret < 0) {
                fprintf(stderr, "Error getting line value: %s\n", strerror(-ret));
                return -1;
            }
            current_state = ret;

            if (current_state != last_state) {
                pulse_count++;
                last_state = current_state;
            }

            if (pulse_count > 100) {
                fprintf(stderr, "Timeout waiting for edge\n");
                return -1;
            }

            usleep(1); // Check every 1us
        }

        if (pulse_count > 100) {
            fprintf(stderr, "Timeout waiting for edge\n");
            return -1;
        }

        pulse_count = 0;

        if (current_state == 0) {
            data[i / 8] <<= 1;
            if (pulse_count > 20) { // > 20us
                data[i / 8] |= 1;
            }
        }
    }

    // Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    return 0;
}

int main() {
    int ret;
    float temperature, humidity;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, DHT22_GPIO);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "dht22", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        ret = read_dht22(&temperature, &humidity);
        if (ret == 0) {
            printf("Temperature: %.1f°C, Humidity: %.1f%%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading DHT22 sensor\n");
        }

        sleep(2);
    }

    // Release GPIO line and close chip (this part is never reached in the current loop)
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int result;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO modes to output */
    result = gpioSetMode(GPIO_17, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode: %d\n", GPIO_17, result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetMode(GPIO_22, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode: %d\n", GPIO_22, result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetMode(GPIO_27, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode: %d\n", GPIO_27, result);
        gpioTerminate();
        return 1;
    }

    /* Set PWM frequency to 1000 Hz */
    result = gpioSetPWMfrequency(GPIO_17, 1000);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d: %d\n", GPIO_17, result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetPWMfrequency(GPIO_22, 1000);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d: %d\n", GPIO_22, result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetPWMfrequency(GPIO_27, 1000);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d: %d\n", GPIO_27, result);
        gpioTerminate();
        return 1;
    }

    /* Set PWM range to 255 */
    result = gpioSetPWMrange(GPIO_17, 255);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d: %d\n", GPIO_17, result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetPWMrange(GPIO_22, 255);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d: %d\n", GPIO_22, result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetPWMrange(GPIO_27, 255);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d: %d\n", GPIO_27, result);
        gpioTerminate();
        return 1;
    }

    /* Set PWM duty cycle to 128 */
    result = gpioPWM(GPIO_17, 128);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d: %d\n", GPIO_17, result);
        gpioTerminate();
        return 1;
    }
    result = gpioPWM(GPIO_22, 128);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d: %d\n", GPIO_22, result);
        gpioTerminate();
        return 1;
    }
    result = gpioPWM(GPIO_27, 128);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d: %d\n", GPIO_27, result);
        gpioTerminate();
        return 1;
    }

    /* Set PWM enable to 1 */
    result = gpioPWM(GPIO_17, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM enable for GPIO %d: %d\n", GPIO_17, result);
        gpioTerminate();
        return 1;
    }
    result = gpioPWM(GPIO_22, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM enable for GPIO %d: %d\n", GPIO_22, result);
        gpioTerminate();
        return 1;
    }
    result = gpioPWM(GPIO_27, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM enable for GPIO %d: %d\n", GPIO_27, result);
        gpioTerminate();
        return 1;
    }

    /* Register signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Main loop */
    while (!terminate) {
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n", GPIO_17, gpioGetPWMdutycycle(GPIO_17), GPIO_22, gpioGetPWMdutycycle(GPIO_22), GPIO_27, gpioGetPWMdutycycle(GPIO_27));
        gpioDelay(500000); // 0.5 seconds
    }

    /* Set PWM enable to 0 */
    gpioPWM(GPIO_17, 0);
    gpioPWM(GPIO_22, 0);
    gpioPWM(GPIO_27, 0);

    /* Terminate pigpio library */
    gpioTerminate();

    return 0;
}

