// Define GPIO pins
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *gpio_line_1;
struct gpiod_line *gpio_line_2;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully.\n", sig);

    // Release GPIO lines
    if (gpio_line_1) {
        gpiod_line_release(gpio_line_1);
    }
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int ret;
    int current_state_1, current_state_2;
    struct gpiod_line_request_config config;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", CHIP_NAME, strerror(errno));
        return 1;
    }

    // Get GPIO line for pin 1
    gpio_line_1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!gpio_line_1) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_1, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line for pin 2
    gpio_line_2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!gpio_line_2) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_2, strerror(errno));
        gpiod_line_release(gpio_line_1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure GPIO line request
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio-control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    // Request GPIO line 1 as output
    ret = gpiod_line_request(gpio_line_1, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_PIN_1, strerror(errno));
        gpiod_line_release(gpio_line_2);
        gpiod_line_release(gpio_line_1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line 2 as output
    ret = gpiod_line_request(gpio_line_2, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_PIN_2, strerror(errno));
        gpiod_line_release(gpio_line_1);
        gpiod_line_release(gpio_line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read current state of GPIO lines
        current_state_1 = gpiod_line_get_value(gpio_line_1);
        current_state_2 = gpiod_line_get_value(gpio_line_2);

        // Print current state
        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, current_state_1, GPIO_PIN_2, current_state_2);

        // Toggle GPIO 1
        if (current_state_1 == 0) {
            ret = gpiod_line_set_value(gpio_line_1, 1);
            if (ret < 0) {
                fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_PIN_1, strerror(errno));
                break; // Exit loop on error
