// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_WTIME           (0x03)
#define TCS34725_AILTL           (0x04)
#define TCS34725_AILTH           (0x05)
#define TCS34725_AIHTL           (0x06)
#define TCS34725_AIHTH           (0x07)
#define TCS34725_ID              (0x12)
#define TCS34725_STATUS          (0x13)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)
#define TCS34725_PDATA           (0x1C)
#define TCS34725_CONTROL         (0x0F)

// Enable Register Values
#define TCS34725_ENABLE_AIEN     (0x10)
#define TCS34725_ENABLE_WEN      (0x08)
#define TCS34725_ENABLE_AEN      (0x02)
#define TCS34725_ENABLE_PON      (0x01)

// Integration Time Options
#define TCS34725_INTEGRATIONTIME_2_4MS  (0xFF)  // 2.4ms - 1 cycle    - Max Count: 1024
#define TCS34725_INTEGRATIONTIME_24MS   (0xF6)  // 24ms  - 10 cycles   - Max Count: 10240
#define TCS34725_INTEGRATIONTIME_50MS   (0xEB)  // 50ms  - 20 cycles   - Max Count: 20480
#define TCS34725_INTEGRATIONTIME_101MS  (0xD5)  // 101ms - 42 cycles   - Max Count: 42592
#define TCS34725_INTEGRATIONTIME_154MS  (0xC0)  // 154ms - 64 cycles   - Max Count: 65535
#define TCS34725_INTEGRATIONTIME_238MS  (0x80)  // 238ms - 98 cycles   - Max Count: 65535

// Gain Options
#define TCS34725_GAIN_1X            (0x00)
#define TCS34725_GAIN_4X            (0x01)
#define TCS34725_GAIN_16X           (0x02)
#define TCS34725_GAIN_60X           (0x03)

// Global Variables
static int i2c_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Signal Handler
static void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

// Function to write a register value
int write_register(int fd, unsigned char reg, unsigned char value)
{
    unsigned char buf[2];
    buf[0] = TCS34725_COMMAND_BIT | reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a register value
int read_register(int fd, unsigned char reg, unsigned char *value)
{
    unsigned char buf[1];
    buf[0] = TCS34725_COMMAND_BIT | reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *value = buf[0];
    return 0;
}

// Function to initialize the TCS34725
int initialize_tcs34725(int fd)
{
    unsigned char id;

    // Check the ID register
    if (read_register(fd, TCS34725_ID, &id) != 0) {
        fprintf(stderr, "Error reading ID register\n");
        return -1;
    }

    if (id != 0x44) {
        fprintf(stderr, "Incorrect ID value: 0x%02x\n", id);
        return -1;
    }

    // Enable power and ALS
    if (write_register(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) != 0) return -1;
    usleep(3000); // Wait for power-on (3ms)
    if (write_register(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0) return -1;

    // Set integration time
    if (write_register(fd, TCS34725_ATIME, TCS34725_INTEGRATIONTIME_24MS) != 0) return -1;

    // Set gain
    if (write_register(fd, TCS34725_CONTROL, TCS34725_GAIN_1X) != 0) return -1;

    return 0;
}

// Function to read RGBC values
int read_rgbc(int fd, unsigned short *r, unsigned short *g, unsigned short *b, unsigned short *c)
{
    unsigned char buf[8];

    // Read all RGBC values at once
    if (write(fd, (unsigned char[]){TCS34725_COMMAND_BIT | TCS34725_CDATA}, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }
    if (read(fd, buf, 8) != 8) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *c = (buf[1] << 8) | buf[0];
    *r = (buf[3] << 8) | buf[2];
    *g = (buf[5] << 8) | buf[4];
    *b = (buf[7] << 8) | buf[6];

    return 0;
}

int main()
{
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 200000000; // 0.2 seconds
    unsigned short r, g, b, c;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize TCS34725
    if (initialize_tcs34725(i2c_fd) != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("TCS34725 sensor reading... Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (read_rgbc(i2c_fd, &r, &g, &b, &c) == 0) {
            printf("R: %d, G: %d, B: %d, C: %d\n", r, g, b, c);
        } else {
            fprintf(stderr, "Failed to read RGBC values\n");
        }

        if (nanosleep(&sleep_time, NULL) != 0) {
            if (errno == EINTR) {
                printf("Sleep interrupted by signal\n");
            } else {
                perror("nanosleep");
            }
        }
    }

    // Cleanup
    printf("Exiting...\n");
    close(i2c_fd);

    return EXIT_SUCCESS;
}

