                munmap(buffers[j].start, buffers[j].length);
            }
            free(buffers);
            return 1;
        }
    }

    // 7. Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        close(fd);
        for (int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return 1;
    }

    // 8. Capture image and save to file
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        close(fd);
        for (int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return 1;
    }

    snprintf(filename, sizeof(filename), "image_%dx%d.yuyv", IMAGE_WIDTH, IMAGE_HEIGHT);
    fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        close(fd);
        for (int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return 1;
    }

    if (fwrite(buffers[buf.index].start, buf.bytesused, 1, fp) != 1) {
        perror("Error writing to file");
        fclose(fp);
        close(fd);
        for (int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return 1;
    }

    fclose(fp);

    // 9. Requeue the buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        close(fd);
        for (int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return 1;
    }

    // 10. Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        close(fd);
        for (int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return 1;
    }

    // 11. Unmap buffers
    for (int i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            perror("Error unmapping buffer");
        }
    }

    // 12. Free buffer array
    free(buffers);

    // 13. Close device
    close(fd);

    printf("Image captured and saved as %s\n", filename);

    return 0;
}

