    ret = trigger_pulse();
    if (ret < 0) {
        fprintf(stderr, "Error triggering pulse\n");
        return -1;
    }

    // Wait for echo to go high (with timeout)
    int timeout_count = 0;
    while (1) {
        int value = gpiod_line_get_value(echo_line);
        if (value < 0) {
            fprintf(stderr, "Error reading echo line\n");
            return -1;
        }
        if (value == 1) {
            break;
        }
        timeout_count++;
        if (timeout_count > 100000) { // Timeout after 100ms
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1;
        }
        usleep(1); // Small delay to avoid busy-waiting
    }

    // Record the start time
    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

    // Wait for echo to go low (with timeout)
    timeout_count = 0;
    while (1) {
        int value = gpiod_line_get_value(echo_line);
        if (value < 0) {
            fprintf(stderr, "Error reading echo line\n");
            return -1;
        }
        if (value == 0) {
