        timeout_count++;
        if (timeout_count > 100000) { // Timeout after 100ms
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1;
        }
        usleep(1); // Small delay to avoid busy-waiting
    }

    // Record the end time
    clock_gettime(CLOCK_MONOTONIC, &end);
    end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;

    // Calculate the pulse width in nanoseconds
    elapsed_ns = end_ns - start_ns;

    // Calculate the distance in centimeters (speed of sound: 343 m/s)
    // distance = (pulse_width * 0.000000001) / 2 * 34300
    double distance = (double)elapsed_ns / 2.0 / 1000000000.0 * 34300.0;

