        ts.tv_nsec = 200000000; // 0.2 seconds
        nanosleep(&ts, NULL);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define DELAY_US 10000 // 10 milliseconds

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    int gpio_status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpio_status = gpioGetMode(GPIO_PIN);
    if (gpio_status != PI_OUTPUT) {
        fprintf(stderr, "Failed to set GPIO %d as output.  Current mode: %d\n", GPIO_PIN, gpio_status);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Set pixel colour to red (1, 0, 0)
        gpioWrite(GPIO_PIN, 1);
        gpioDelay(DELAY_US);

        // Set pixel colour to green (0, 1, 0)
        gpioWrite(GPIO_PIN, 0);
        gpioDelay(DELAY_US);

        // Set pixel colour to blue (0, 0, 1)
        gpioWrite(GPIO_PIN, 1);
        gpioDelay(DELAY_US);
    }

    // Clean up and exit
    gpioWrite(GPIO_PIN, 0); // Turn off the LED
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIOCHIP "gpiochip0"
#define GPIO17 17
#define GPIO27 27

static struct gpiod_chip *chip;
static struct gpiod_line *gpio17_line;
static struct gpiod_line *gpio27_line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

int main() {
    int ret;
    unsigned int value;

    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO 17 line
    gpio17_line = gpiod_chip_get_line(chip, GPIO17);
    if (!gpio17_line) {
        fprintf(stderr, "Error getting GPIO %d line: %s\n", GPIO17, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get GPIO 27 line
    gpio27_line = gpiod_chip_get_line(chip, GPIO27);
    if (!gpio27_line) {
        fprintf(stderr, "Error getting GPIO %d line: %s\n", GPIO27, strerror(errno));
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 17 as output
    ret = gpiod_line_request_output(gpio17_line, "gpio-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO17, strerror(errno));
        gpiod_line_release(gpio27_line);
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 27 as output
    ret = gpiod_line_request_output(gpio27_line, "gpio-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO27, strerror(errno));
        gpiod_line_release(gpio17_line);
        gpiod_line_release(gpio27_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d and GPIO %d set to output mode (initial value: 0). Press Ctrl+C to exit.\n", GPIO17, GPIO27);

    while (keep_running) {
        // Read current values
        value = gpiod_line_get_value(gpio17_line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO %d value: %s\n", GPIO17, strerror(errno));
            break;
        }

        value = gpiod_line_get_value(gpio27_line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO %d value: %s\n", GPIO27, strerror(errno));
            break;
        }

        // Print current values
        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO17, value, GPIO27, value);

        // Sleep for 1 second
        sleep(1);
    }

    // Release GPIO lines
    gpiod_line_release(gpio17_line);
    gpiod_line_release(gpio27_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Exited cleanly.\n");
    return EXIT_SUCCESS;
}

