#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the GPIO pins to be used
#define GPIO_1 1
#define GPIO_4 4
#define GPIO_5 5
#define GPIO_6 6
#define GPIO_21 21
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *gpio_lines[8];

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully.\n", sig);

    // Release GPIO lines
    for (int i = 0; i < 8; i++)
    {
        if (gpio_lines[i])
        {
            gpiod_line_release(gpio_lines[i]);
        }
    }

    // Close the GPIO chip
    if (chip)
    {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip)
    {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    gpio_lines[0] = gpiod_chip_get_line(chip, GPIO_1);
    gpio_lines[1] = gpiod_chip_get_line(chip, GPIO_4);
    gpio_lines[2] = gpiod_chip_get_line(chip, GPIO_5);
    gpio_lines[3] = gpiod_chip_get_line(chip, GPIO_6);
    gpio_lines[4] = gpiod_chip_get_line(chip, GPIO_21);
    gpio_lines[5] = gpiod_chip_get_line(chip, GPIO_22);
    gpio_lines[6] = gpiod_chip_get_line(chip, GPIO_23);
    gpio_lines[7] = gpiod_chip_get_line(chip, GPIO_24);

    for (int i = 0; i < 8; i++)
    {
        if (!gpio_lines[i])
        {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", i + 1, strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < i; j++)
            {
                gpiod_line_release(gpio_lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Request GPIO lines for output
    for (int i = 0; i < 8; i++)
    {
        if (gpiod_line_request_output(gpio_lines[i], "gpio_output", 0) < 0)
        {
            fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", i + 1, strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j <= i; j++)
            {
                gpiod_line_release(gpio_lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop to set and report the state of GPIO lines
    while (1)
    {
        // Set GPIO lines to 0 or 1 (example values)
        for (int i = 0; i < 8; i++)
        {
            int value = (i % 2 == 0) ? 0 : 1; // Alternate between 0 and 1
            if (gpiod_line_set_value(gpio_lines[i], value) < 0)
            {
                fprintf(stderr, "Error setting GPIO line %d value: %s\n", i + 1, strerror(errno));
                // Release previously acquired lines
                for (int j = 0; j <= i; j++)
                {
                    gpiod_line_release(gpio_lines[j]);
                }
                gpiod_chip_close(chip);
                return 1;
            }
        }

        // Report the state of GPIO lines
        printf("GPIO 1: %d, GPIO 4: %d, GPIO 5: %d, GPIO 6: %d, GPIO 21: %d, GPIO 22: %d, GPIO 23: %d, GPIO 24: %d\n",
               gpiod_line_get_value(gpio_lines[0]),
               gpiod_line_get_value(gpio_lines[1]),
               gpiod_line_get_value(gpio_lines[2]),
               gpiod_line_get_value(gpio_lines[3]),
               gpiod_line_get_value(gpio_lines[4]),
               gpiod_line_get_value(gpio_lines[5]),
               gpiod_line_get_value(gpio_lines[6]),
               gpiod_line_get_value(gpio_lines[7]));

        // Sleep for a short interval
        usleep(500000); // 0.5 seconds
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0" // Adjust if necessary
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define BUFFER_COUNT 1

struct buffer {
    void   *start;
    size_t  length;
};

static int                  fd                  = -1;
static struct buffer         *buffers             = NULL;
static unsigned int          n_buffers            = 0;
static int                  frame_count           = 0;
static FILE                 *fp                   = NULL;
static volatile sig_atomic_t stop_flag            = 0;

static void signal_handler(int sig)
{
    printf("Caught signal %d, exiting...\n", sig);
    stop_flag = 1;
}

static int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

static int init_device(const char *dev_name, unsigned int *width, unsigned int *height)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;

    fd = open(dev_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Cannot open device");
        return -1;
    }

    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", dev_name);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", dev_name);
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = *width;
    fmt.fmt.pix.height = *height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG; // Request JPEG format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory on %s\n", dev_name);
        close(fd);
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));

    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        close(fd);
        return -1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            perror("VIDIOC_QUERYBUF");
            close(fd);
            free(buffers);
            return -1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            perror("mmap");
            close(fd);
            free(buffers);
            return -1;
        }
    }

    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            perror("VIDIOC_QBUF");
            close(fd);
            for(int j = 0; j < n_buffers; ++j) {
                munmap(buffers[j].start, buffers[j].length);
            }
            free(buffers);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        perror("VIDIOC_STREAMON");
        close(fd);
        for(int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return -1;
    }

    *width = fmt.fmt.pix.width;
    *height = fmt.fmt.pix.height;

    return 0;
}

static int capture_image(FILE *fp, const char *filename)
{
    struct v4l2_buffer buf;
    struct v4l2_streamparm streamparm;
    unsigned int rate = 20; // Frames per second

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    memset(&streamparm, 0, sizeof(streamparm));
    streamparm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    streamparm.parm.capture.timeperframe.numerator = 1;
    streamparm.parm.capture.timeperframe.denominator = rate;

    if (-1 == xioctl(fd, VIDIOC_S_PARM, &streamparm)) {
        perror("VIDIOC_S_PARM");
        return -1;
    }

    if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    if (fwrite(buffers[buf.index].start, buf.bytesused, 1, fp) != 1) {
        perror("fwrite");
        return -1;
    }

    frame_count++;

    return 0;
}

static void cleanup(void)
{
    unsigned int i;

    for (i = 0; i < n_buffers; ++i) {
        if (-1 == munmap(buffers[i].start, buffers[i].length)) {
            perror("munmap");
        }
    }

    free(buffers);

    if (-1 != fd) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
            perror("VIDIOC_STREAMOFF");
        }

        close(fd);
    }

    if (fp) {
        fclose(fp);
    }
}

int main(int argc, char *argv[])
{
    unsigned int width, height;
    char filename[64];
    struct timespec sleep_time;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (0 != init_device(DEVICE_NAME, &width, &height)) {
        fprintf(stderr, "Failed to initialize device\n");
        return EXIT_FAILURE;
    }

    printf("Device initialized. Width: %u, Height: %u\n", width, height);

    fp = fopen("captured_image.jpg", "wb");
    if (!fp) {
        perror("Failed to open output file");
        cleanup();
        return EXIT_FAILURE;
    }

    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 50000000; // 0.05 seconds

    while (!stop_flag) {
        if (capture_image(fp, "captured_image.jpg") != 0) {
            fprintf(stderr, "Failed to capture image\n");
            break;
        }

        printf("Captured frame: %u\n", frame_count);
        nanosleep(&sleep_time, NULL);
    }

    cleanup();

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_PRESSURE_MSB 0xF7
#define BME280_REG_HUMIDITY_MSB 0xFD
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_ID 0xD0

// Calibration data registers
#define BME280_REG_CALIB_00 0x88

// Global variables
int i2c_fd;
volatile sig_atomic_t stop_flag = 0;

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

struct bme280_calib_data calib;

// Signal handler for Ctrl+C
void sigint_handler(int sig) {
    stop_flag = 1;
    printf("\nExiting...\n");
}

// Function to read a single byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg_addr, uint8_t *data) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return 0;
}

// Function to write a single byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg_addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BME280
int read_calibration_data(int fd, struct bme280_calib_data *cal) {
    uint8_t buffer[26];
    if (read(fd, buffer, 26) != 26) {
        perror("Failed to read calibration data");
        return -1;
    }

    cal->dig_T1 = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    cal->dig_T2 = (int16_t)buffer[2] | ((int16_t)buffer[3] << 8);
    cal->dig_T3 = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    cal->dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    cal->dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    cal->dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    cal->dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    cal->dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    cal->dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
    cal->dig_P7 = (int16_t)buffer[18] | ((int16_t)buffer[19] << 8);
    cal->dig_P8 = (int16_t)buffer[20] | ((int16_t)buffer[21] << 8);
    cal->dig_P9 = (int16_t)buffer[22] | ((int16_t)buffer[23] << 8);
    cal->dig_H1 = buffer[25];

    uint8_t buffer_h[7];
    if (read(fd, buffer_h, 7) != 7) {
        perror("Failed to read humidity calibration data");
        return -1;
    }

