#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096

int i2c_fd;
volatile sig_atomic_t stop_flag = 0;

void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    stop_flag = 1;
}

int read_ads1115(int i2c_fd, int addr) {
    unsigned char buf[2];
    int16_t reading;
    int ret;

    // Configure ADS1115 for single-ended channel 0, 4.096V range, single-shot mode
    buf[0] = CONFIG_REG;
    buf[1] = 0x83; // 0b10000011:  OS = 1 (start single conversion), MUX = 100 (AIN0), PGA = 001 (FS = +/-4.096V), MODE = 1 (single-shot), DR = 100 (128 SPS), COMP_MODE = 0 (traditional comparator)
    ret = write(i2c_fd, buf, 2);
    if (ret != 2) {
        perror("Failed to write config register");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read conversion register
    buf[0] = CONVERSION_REG;
    ret = write(i2c_fd, buf, 1);
    if (ret != 1) {
        perror("Failed to write conversion register address");
        return -1;
    }

    ret = read(i2c_fd, buf, 2);
    if (ret != 2) {
        perror("Failed to read conversion register");
        return -1;
    }

    reading = (buf[0] << 8) | buf[1];
    return reading;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 200000000; // 0.2 seconds
    int reading;

    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    printf("ADS1115 reader. Press Ctrl+C to exit.\n");

    while (!stop_flag) {
        reading = read_ads1115(i2c_fd, ADS1115_ADDR);
        if (reading >= 0) {
            printf("Reading: %d\n", reading);
        } else {
            fprintf(stderr, "Error reading ADS1115\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        keep_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting...\n");
    }
}

int main() {
    int ret;
    int value;

    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Read current value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        // Print the state
        printf("GPIO %d: %s\n", GPIO_PIN, (value == 0) ? "LOW" : "HIGH");

        // Wait 60 seconds
        sleep(60);
    }

    // Cleanup
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

