// Function to read a 16-bit value from the MPU6050
int16_t read_word_2c(int fd, uint8_t reg) {
    int16_t high, low, value;

    high = ioctl(fd, I2C_SLAVE, reg);
    if (high < 0) {
        perror("Failed to acquire bus access");
        return -1;
    }

    low = ioctl(fd, I2C_SLAVE, reg + 1);
    if (low < 0) {
        perror("Failed to acquire bus access");
        return -1;
    }

    value = (high << 8) | low;
    return value;
}

