#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <signal.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting and releasing I2C bus...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the MPU6050
int16_t read_mpu6050_value(int reg) {
    uint8_t buffer[2];
    int16_t value;

    // Write the register address to read from
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        return 0; // Or some error value
    }

    // Read two bytes from the register
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        return 0; // Or some error value
    }

    // Combine the two bytes into a 16-bit value
    value = (buffer[0] << 8) | buffer[1];
    return value;
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // I2C device file

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep mode bit)
    uint8_t wake_up_value = 0x00;
    if (write(i2c_fd, &wake_up_value, 1) != 1) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        return 1;
    }

    // Read 100 values from the MPU6050
    for (int i = 0; i < 100; i++) {
        // Read accelerometer data
        int16_t accel_x = read_mpu6050_value(ACCEL_XOUT_H);
        int16_t accel_y = read_mpu6050_value(ACCEL_YOUT_H);
        int16_t accel_z = read_mpu6050_value(ACCEL_ZOUT_H);

        // Print the values to standard output
        printf("AccelX: %d, AccelY: %d, AccelZ: %d\n", accel_x, accel_y, accel_z);
    }

    // Close the I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIOCHIP "gpiochip0"
#define GPIO14 14
#define GPIO15 15

static struct gpiod_chip *chip;
static struct gpiod_line *gpio14_line;
static struct gpiod_line *gpio15_line;
static volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    keep_running = 0;
}

int main() {
    int ret;
    unsigned int value14, value15;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return 1;
    }

    gpio14_line = gpiod_chip_get_line(chip, GPIO14);
    if (!gpio14_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO14, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    gpio15_line = gpiod_chip_get_line(chip, GPIO15);
    if (!gpio15_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO15, strerror(errno));
        gpiod_line_release(gpio14_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(gpio14_line, "gpio-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO14, strerror(errno));
        gpiod_line_release(gpio15_line);
        gpiod_line_release(gpio14_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(gpio15_line, "gpio-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO15, strerror(errno));
        gpiod_line_release(gpio14_line);
        gpiod_line_release(gpio15_line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d and %d output control started. Press Ctrl+C to exit.\n", GPIO14, GPIO15);

    while (keep_running) {
        ret = gpiod_line_get_value(gpio14_line);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO14, strerror(errno));
        } else {
            value14 = ret;
        }

        ret = gpiod_line_get_value(gpio15_line);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO15, strerror(errno));
        } else {
            value15 = ret;
        }

        printf("GPIO %d: %u, GPIO %d: %u\n", GPIO14, value14, GPIO15, value15);
        sleep(5);
    }

    printf("Exiting...\n");

    gpiod_line_set_value(gpio14_line, 0);
    gpiod_line_release(gpio14_line);
    gpiod_line_release(gpio15_line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define MQTT_HOST "localhost" // Change to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/temperature"
#define SENSOR_GPIO 4
#define VALID_TEMP_MIN 10.0
#define VALID_TEMP_MAX 40.0
#define PUBLISH_INTERVAL 0.01 // 10 Hz

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
double read_temperature();
int validate_temperature(double temperature);
int publish_temperature(double temperature);
void signal_handler(int signum);
int mqtt_connect_and_subscribe();
void mqtt_disconnect();

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, exiting gracefully.\n");
        running = 0;
    }
}

// Read temperature from the sensor
double read_temperature() {
    int raw_value = gpioRead(SENSOR_GPIO);
    if (raw_value < 0) {
        fprintf(stderr, "Error reading sensor value: %d\n", raw_value);
        return -1.0; // Indicate error
    }

    // Simulate temperature based on GPIO value (0 or 1)
    // In a real application, you'd use an ADC and convert the value to temperature.
    if (raw_value == 0) {
        return 15.0; // Example: GPIO LOW = 15°C
    } else {
        return 30.0; // Example: GPIO HIGH = 30°C
    }
}

// Validate temperature
int validate_temperature(double temperature) {
    if (temperature < VALID_TEMP_MIN || temperature > VALID_TEMP_MAX) {
        fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
        return 0; // Invalid
    }
    return 1; // Valid
}

// Publish temperature to MQTT broker
int publish_temperature(double temperature) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%.2f", temperature);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return 0; // Indicate error
    }
    return 1; // Indicate success
}

// Connect to MQTT broker and subscribe to topic
int mqtt_connect_and_subscribe() {
    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        return 0;
    }

    ret = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error subscribing to topic: %s\n", mosquitto_strerror(ret));
        return 0;
    }

    return 1; // Indicate success
}

// Disconnect from MQTT broker
void mqtt_disconnect() {
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode
    gpioSetMode(SENSOR_GPIO, PI_INPUT);

    // Initialize libmosquitto
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Connect to MQTT broker
    if (!mqtt_connect_and_subscribe()) {
        fprintf(stderr, "Failed to connect to MQTT broker. Exiting.\n");
        mqtt_disconnect();
        gpioTerminate();
        return 1;
    }

    printf("Temperature publisher started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        double temperature = read_temperature();
        if (temperature >= 0.0) {
            if (validate_temperature(temperature)) {
                if (!publish_temperature(temperature)) {
                    fprintf(stderr, "Failed to publish temperature.\n");
                }
            } else {
                fprintf(stderr, "Temperature invalid, not publishing.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        usleep((int)(PUBLISH_INTERVAL * 1000000)); // Sleep for PUBLISH_INTERVAL seconds
    }

    // Cleanup
    mqtt_disconnect();
    gpioTerminate();

    printf("Temperature publisher stopped.\n");

    return 0;
}

#include <stdio.h>
