// Define the chip name (adjust if necessary)
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *gpio_line_1;
struct gpiod_line *gpio_line_2;
struct gpiod_line *gpio_line_3;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully...\n", sig);

    // Release GPIO lines
    if (gpio_line_1) {
        gpiod_line_release(gpio_line_1);
    }
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }
    if (gpio_line_3) {
        gpiod_line_release(gpio_line_3);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int ret;
    unsigned int value;

    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line handles
    gpio_line_1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    gpio_line_2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    gpio_line_3 = gpiod_chip_get_line(chip, GPIO_PIN_3);

    if (!gpio_line_1 || !gpio_line_2 || !gpio_line_3) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(gpio_line_1, "gpio_output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 1 for output");
        gpiod_line_release(gpio_line_1);
        gpiod_line_release(gpio_line_2);
        gpiod_line_release(gpio_line_3);
        gpiod_chip_close(chip);
