    if (ret < 0) {
        perror("Error requesting GPIO line 2 for output");
        gpiod_line_release(gpio_line_1);
        gpiod_line_release(gpio_line_2);
        gpiod_line_release(gpio_line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(gpio_line_3, "gpio_output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 3 for output");
        gpiod_line_release(gpio_line_1);
        gpiod_line_release(gpio_line_2);
        gpiod_line_release(gpio_line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO values
        ret = gpiod_line_set_value(gpio_line_1, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 1 value");
