        // Reverse the state
        ret = gpiod_line_set_value(gpio_line_1, 0);
        if (ret < 0) {
            perror("Error setting GPIO line 1 value");
            break;
        }

        ret = gpiod_line_set_value(gpio_line_2, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 2 value");
            break;
        }

        ret = gpiod_line_set_value(gpio_line_3, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 3 value");
            break;
