               gpiod_line_get_value_str(gpio_line_1),
               gpiod_line_get_value_str(gpio_line_2),
               gpiod_line_get_value_str(gpio_line_3));

        // Wait for 2 seconds
        sleep(2);
    }

    // Release GPIO lines and close chip (in case of error)
    gpiod_line_release(gpio_line_1);
    gpiod_line_release(gpio_line_2);
    gpiod_line_release(gpio_line_3);
    gpiod_chip_close(chip);

