// Publishes the temperature data to the MQTT broker
int publish_data(double temperature) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    char payload[100];
    snprintf(payload, sizeof(payload), "{\"timestamp\": \"%s\", \"temperature\": %.2f}", timestamp, temperature);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
