#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        int start = gpioTick();
        while (gpioRead(ECHO_PIN) == 0) {
            if (gpioTick() - start > 50000) { // Timeout after 50ms
                fprintf(stderr, "Timeout waiting for echo start\n");
                continue; // Retry
            }
        }
        int echo_start = gpioTick();

        while (gpioRead(ECHO_PIN) == 1) {
            if (gpioTick() - echo_start > 50000) { // Timeout after 50ms
                fprintf(stderr, "Timeout waiting for echo end\n");
                continue; // Retry
            }
        }
        int echo_end = gpioTick();

        int pulse_width = echo_end - echo_start;

        if (pulse_width < 0) {
            fprintf(stderr, "Error: Invalid pulse width reading\n");
            continue;
        }

        if (pulse_width > 50000) {
            fprintf(stderr, "Error: Invalid pulse width reading (out of range)\n");
            continue;
        }

        printf("Pulse Width: %d us\n", pulse_width);

        gpioDelay(200000); // 0.2 seconds
    }

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

