#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <MQTTClient.h>

// Configuration
#define MQTT_BROKER "tcp://localhost:1883" // Replace with your broker address
#define MQTT_CLIENT_ID "rpi_sensor_publisher"
#define MQTT_TOPIC "rpi/sensor_data"
#define SENSOR_GPIO 4 // GPIO pin connected to the sensor
#define VALID_READING_RANGE 0, 100 // Minimum and maximum sensor values
#define PUBLISH_INTERVAL_SEC 5

// Global variables
static volatile int running = 1;
static MQTTClient client;

// Function prototypes
int read_sensor();
int validate_reading(int reading);
int publish_reading(int reading);
void signal_handler(int signal);
int mqtt_connect();
void mqtt_disconnect();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Reads the sensor value from the specified GPIO pin
int read_sensor() {
    return gpioRead(SENSOR_GPIO);
}

// Validates the sensor reading against a defined range
int validate_reading(int reading) {
    return (reading >= VALID_READING_RANGE[0] && reading <= VALID_READING_RANGE[1]);
}

// Publishes the sensor reading to the MQTT broker
int publish_reading(int reading) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%d", reading);

    int rc = MQTTClient_publishMessage(client, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        return -1;
    }
    printf("Published reading: %d\n", reading);
    return 0;
}

// Connects to the MQTT broker
int mqtt_connect() {
    int rc;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create client, return code %d\n", rc);
        return -1;
    }

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect, return code %d\n", rc);
        MQTTClient_destroy(&client);
        return -1;
    }

    printf("Connected to MQTT broker\n");
    return 0;
}

// Disconnects from the MQTT broker
void mqtt_disconnect() {
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    printf("Disconnected from MQTT broker\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(SENSOR_GPIO, PI_INPUT);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Connect to MQTT broker
    if (mqtt_connect() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        int reading = read_sensor();
        if (reading >= 0) {
            if (validate_reading(reading)) {
                if (publish_reading(reading) != 0) {
                    fprintf(stderr, "Failed to publish reading\n");
                }
            } else {
                fprintf(stderr, "Invalid sensor reading: %d\n", reading);
            }
        } else {
            fprintf(stderr, "Failed to read sensor\n");
        }

        sleep(PUBLISH_INTERVAL_SEC);
    }

    // Disconnect from MQTT broker
    mqtt_disconnect();

    // Release GPIO pin
    gpioSetMode(SENSOR_GPIO, PI_INPUT); // Set back to input to avoid issues

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

