// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_DIFF_0_1 0x0000 // Differential P = AIN0, N = AIN1
#define ADS1115_CONFIG_PGA_4_096V 0x0000  // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0080   // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// MQTT broker address and topic
#define MQTT_BROKER_ADDRESS "localhost" // Replace with your broker address
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "home/sensor/ads1115"

// Global variables
int i2c_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read ADC value from ADS1115
int16_t read_ads1115()
{
    char buf[2];
    int16_t adc_value;

    // Write configuration register to start single conversion
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_DIFF_0_1 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion register
    buf[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    adc_value = (buf[0] << 8) | buf[1];

    return adc_value;
}

// Function to publish MQTT message
int publish_mqtt_message(const char *topic, const char *payload)
{
    int ret;

    ret = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

