    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating mosquitto instance\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Connect to MQTT broker
    rc = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    for (int i = 0; i < 10 && !terminate; ++i) {
        // Read ADC value
        adc_value = read_ads1115();
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC value, exiting\n");
            break;
        }

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Format payload
        snprintf(payload, sizeof(payload), "{\"sensor\":\"ads1115\", \"value\":%d, \"timestamp\":\"%s\"}", adc_value, timestamp);

        // Publish MQTT message
        if (publish_mqtt_message(MQTT_TOPIC, payload) != 0) {
            fprintf(stderr, "Error publishing MQTT message\n");
            break;
        }

        printf("Published: %s\n", payload);

        // Wait 1 second
        sleep(1);
    }

    // Clean up
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
