#define GPIO_PIN 4  // BCM GPIO 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int gpio_status;
    int pwm_value = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(GPIO_PIN, 1000); // 1 kHz

    // Set PWM range (adjust as needed, e.g., 0-255 for 8-bit resolution)
    gpioSetPWMrange(GPIO_PIN, 255);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("PWM output on GPIO %d started. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (!terminate) {
        // Increment PWM value (0-255)
        pwm_value = (pwm_value + 1) % 256;

        // Set PWM duty cycle
        gpioPWM(GPIO_PIN, pwm_value);

        // Report PWM value
        printf("PWM Value: %d\n", pwm_value);

