// Define GPIO pins
#define GPIO_5 5
#define GPIO_6 6
#define GPIO_13 13

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *gpio5_line, *gpio6_line, *gpio13_line;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully.\n", sig);

    // Release GPIO lines
    if (gpio5_line) {
        gpiod_line_release(gpio5_line);
    }
    if (gpio6_line) {
        gpiod_line_release(gpio6_line);
    }
    if (gpio13_line) {
        gpiod_line_release(gpio13_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    gpio5_line = gpiod_chip_get_line(chip, GPIO_5);
    gpio6_line = gpiod_chip_get_line(chip, GPIO_6);
    gpio13_line = gpiod_chip_get_line(chip, GPIO_13);

    if (!gpio5_line || !gpio6_line || !gpio13_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio5_line, &config, 0) < 0) {
        perror("Error requesting GPIO 5 for output");
        gpiod_line_release(gpio5_line);
        gpiod_line_release(gpio6_line);
        gpiod_line_release(gpio13_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request(gpio6_line, &config, 0) < 0) {
        perror("Error requesting GPIO 6 for output");
        gpiod_line_release(gpio5_line);
        gpiod_line_release(gpio6_line);
        gpiod_line_release(gpio13_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request(gpio13_line, &config, 0) < 0) {
        perror("Error requesting GPIO 13 for output");
        gpiod_line_release(gpio5_line);
        gpiod_line_release(gpio6_line);
        gpiod_line_release(gpio13_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO states
        int state5 = (rand() % 2); // 0 or 1
        int state6 = (rand() % 2); // 0 or 1
        int state13 = (rand() % 2); // 0 or 1

        if (gpiod_line_set_value(gpio5_line, state5) < 0) {
            perror("Error setting GPIO 5 value");
        }
        if (gpiod_line_set_value(gpio6_line, state6) < 0) {
            perror("Error setting GPIO 6 value");
        }
        if (gpiod_line_set_value(gpio13_line, state13) < 0) {
            perror("Error setting GPIO 13 value");
        }

        // Print current state
        printf("GPIO 5: %d, GPIO 6: %d, GPIO 13: %d\n", state5, state6, state13);

        // Wait for a short period
        usleep(100000); // 100ms
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define MQTT_HOST "localhost" // Change to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/sensor/temperature"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // MCP3008 channel to read

// Global variables
static volatile int running = 1;
static int spi_handle;
static struct mosquitto *mosq = NULL;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
int publish_temperature(float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    // Assuming 3.3V reference, 10-bit ADC, and 10mV/°C
    return (adc_value * 3.3 / 1024) * 100.0;
}

// Function to publish temperature reading to MQTT broker
int publish_temperature(float temperature) {
    char payload[50];
    snprintf(payload, sizeof(payload), "%.2f", temperature);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: MQTT publish failed: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    printf("Published temperature: %.2f °C\n", temperature);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize libmosquitto
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: mosquitto_new failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        return 1;
    }

    // Connect to MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: MQTT connect failed: %s\n", mosquitto_strerror(ret));
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read temperature from MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Publish temperature reading
        if (publish_temperature(temperature) != 0) {
            fprintf(stderr, "Error: Failed to publish temperature\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

