#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0" // Adjust if necessary
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define BUFFER_COUNT 1

struct buffer {
    void   *start;
    size_t  length;
};

static int                  fd                  = -1;
static struct buffer         *buffers             = NULL;
static unsigned int          n_buffers            = 0;
static int                  frame_count           = 0;
static FILE                 *fp                   = NULL;
static volatile sig_atomic_t stop_flag            = 0;

static void signal_handler(int sig)
{
    fprintf(stderr, "Signal %d received, exiting...\n", sig);
    stop_flag = 1;
}

static int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

static int init_device(const char *dev_name, unsigned int *width, unsigned int *height)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;

    fd = open(dev_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Cannot open '%s': %d, %s\n", dev_name, errno, strerror(errno));
        return -1;
    }

    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        fprintf(stderr, "VIDIOC_QUERYCAP error\n");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", dev_name);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", dev_name);
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG; // Request JPEG format
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        fprintf(stderr, "VIDIOC_S_FMT error\n");
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        fprintf(stderr, "VIDIOC_REQBUFS error\n");
        close(fd);
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory on %s\n", dev_name);
        close(fd);
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        close(fd);
        return -1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QUERYBUF error\n");
            close(fd);
            free(buffers);
            return -1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            fprintf(stderr, "mmap error\n");
            close(fd);
            free(buffers);
            return -1;
        }
    }

    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QBUF error\n");
            close(fd);
            for(int j = 0; j < n_buffers; ++j) {
                munmap(buffers[j].start, buffers[j].length);
            }
            free(buffers);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        fprintf(stderr, "VIDIOC_STREAMON error\n");
        close(fd);
        for(int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return -1;
    }

    *width = fmt.fmt.pix.width;
    *height = fmt.fmt.pix.height;

    return 0;
}

static int capture_image(FILE *fp, const char *filename)
{
    struct v4l2_buffer buf;
    struct v4l2_streamparm streamparm;
    unsigned int frame_rate = 1; // Frames per second

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
        fprintf(stderr, "VIDIOC_DQBUF error\n");
        return -1;
    }

    frame_count++;

    // Write the JPEG data to the file
    fwrite(buffers[buf.index].start, buf.bytesused, 1, fp);

    if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
        fprintf(stderr, "VIDIOC_QBUF error\n");
        return -1;
    }

    memset(&streamparm, 0, sizeof(streamparm));
    streamparm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    streamparm.parm.capture.timeperframe.numerator = 1;
    streamparm.parm.capture.timeperframe.denominator = frame_rate;

    if (-1 == xioctl(fd, VIDIOC_S_PARM, &streamparm)) {
        fprintf(stderr, "VIDIOC_S_PARM error\n");
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    unsigned int i;

    if (fd != -1) {
        for (i = 0; i < n_buffers; ++i) {
            if (buffers && buffers[i].start) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
        buffers = NULL;

        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
            fprintf(stderr, "VIDIOC_STREAMOFF error\n");
        }

        close(fd);
        fd = -1;
    }

    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
}

int main(int argc, char *argv[])
{
    unsigned int width, height;
    char filename[64];
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_device(DEVICE_NAME, &width, &height) < 0) {
        fprintf(stderr, "Failed to initialize device\n");
        return EXIT_FAILURE;
    }

    fp = fopen("captured_image.jpg", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        if (capture_image(fp, "captured_image.jpg") < 0) {
            fprintf(stderr, "Failed to capture image\n");
            break;
        }

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);
        printf("Captured image: %s\n", timestamp);

        sleep(1);
    }

    cleanup();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2)

struct buffer {
    void   *start;
    size_t  length;
};

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct buffer *buffers;
    unsigned int n_buffers;
    unsigned int i;
    FILE *fp;

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    // Query capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 4; // Request 4 buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    buffers = calloc(req.count, sizeof(struct buffer));
    if (!buffers) {
        perror("Out of memory");
        close(fd);
        return 1;
    }

    // Map the buffers
    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(fd);
            free(buffers);
            return 1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[n_buffers].start == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            free(buffers);
            return 1;
        }
    }

    // Queue the buffers
    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            close(fd);
            for (int j = 0; j < n_buffers; ++j) {
                munmap(buffers[j].start, buffers[j].length);
            }
            free(buffers);
            return 1;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        close(fd);
        for (int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return 1;
    }

    // Capture an image
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        close(fd);
        for (int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return 1;
    }

    // Save the image to a file
    fp = fopen("captured_image.yuyv", "wb");
    if (!fp) {
        perror("Error opening file");
        close(fd);
        for (int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return 1;
    }

    fwrite(buffers[buf.index].start, buf.bytesused, 1, fp);
    fclose(fp);

    // Requeue the buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error requeuing buffer");
        close(fd);
        for (int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return 1;
    }

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        close(fd);
        for (int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return 1;
    }

    // Unmap buffers
    for (i = 0; i < n_buffers; ++i) {
        munmap(buffers[i].start, buffers[i].length);
    }

    // Free buffers
    free(buffers);

    // Close device
    close(fd);

    printf("Image captured and saved to captured_image.yuyv\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
#define GPIO_LINE_1 2
#define GPIO_LINE_2 3

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *line1 = NULL;
struct gpiod_line *line2 = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully.\n", sig);

    // Release GPIO lines
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int ret;
    int current_state1 = 0;
    int current_state2 = 0;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return 1;
    }

    // Get GPIO line 1
    line1 = gpiod_chip_get_line(chip, GPIO_LINE_1);
    if (!line1) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE_1, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line 2
    line2 = gpiod_chip_get_line(chip, GPIO_LINE_2);
    if (!line2) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE_2, strerror(errno));
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line 1 as output
    ret = gpiod_line_request_output(line1, "gpio_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_LINE_1, strerror(errno));
        gpiod_line_release(line2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line 2 as output
    ret = gpiod_line_request_output(line2, "gpio_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_LINE_2, strerror(errno));
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle the state of GPIO line 1
        current_state1 = !current_state1;
        ret = gpiod_line_set_value(line1, current_state1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_LINE_1, strerror(errno));
            break; // Exit loop on error
        }

        // Toggle the state of GPIO line 2
        current_state2 = !current_state2;
        ret = gpiod_line_set_value(line2, current_state2);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_LINE_2, strerror(errno));
            break; // Exit loop on error
        }

        // Print the current state of the GPIO lines
        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_LINE_1, current_state1, GPIO_LINE_2, current_state2);

        // Wait for 0.5 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO lines and close chip (in case of error)
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 1;
}

