#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIOCHIP "gpiochip0"
#define GPIO18 18
#define GPIO19 19

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *gpio18_line = NULL;
static struct gpiod_line *gpio19_line = NULL;
static volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    int ret;
    int gpio18_value, gpio19_value;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get GPIO 18 line
    gpio18_line = gpiod_chip_get_line(chip, GPIO18);
    if (!gpio18_line) {
        perror("gpiod_chip_get_line (GPIO18)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get GPIO 19 line
    gpio19_line = gpiod_chip_get_line(chip, GPIO19);
    if (!gpio19_line) {
        perror("gpiod_chip_get_line (GPIO19)");
        gpiod_line_release(gpio18_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 18 as output
    ret = gpiod_line_request_output(gpio18_line, "gpio-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO18)");
        gpiod_line_release(gpio18_line);
        gpiod_line_release(gpio19_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 19 as output
    ret = gpiod_line_request_output(gpio19_line, "gpio-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO19)");
        gpiod_line_release(gpio18_line);
        gpiod_line_release(gpio19_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO 18 to 1
        ret = gpiod_line_set_value(gpio18_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO18)");
            break;
        }

        // Set GPIO 19 to 0
        ret = gpiod_line_set_value(gpio19_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO19)");
            break;
        }

        // Report the state
        printf("GPIO18: %d, GPIO19: %d\n", gpio18_value, gpio19_value);

        // Wait 0.5 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 0.5 seconds
        nanosleep(&sleep_time, NULL);

        // Set GPIO 18 to 0
        ret = gpiod_line_set_value(gpio18_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO18)");
            break;
        }

        // Set GPIO 19 to 1
        ret = gpiod_line_set_value(gpio19_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO19)");
            break;
        }

        // Report the state
        printf("GPIO18: %d, GPIO19: %d\n", gpio18_value, gpio19_value);

        // Wait 0.5 seconds
        sleep_time.tv_nsec = 500000000; // 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (gpio18_line) {
        gpiod_line_release(gpio18_line);
    }
    if (gpio19_line) {
        gpiod_line_release(gpio19_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B9600

int main() {
    int uart_fd;
    struct termios tty;
    char buffer[256];
    size_t bytes_read;

    // Open the serial port
    uart_fd = open(UART_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd < 0) {
        perror("Error opening serial port");
        return EXIT_FAILURE;
    }

    // Configure the serial port
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;            // read doesn't block
    tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    // Read data from the serial port
    bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);
    if (bytes_read < 0) {
        perror("Error reading from serial port");
        close(uart_fd);
        return EXIT_FAILURE;
    }
    buffer[bytes_read] = '\0'; // Null-terminate the string

    // Print the data to standard output
    printf("Received: %s\n", buffer);

    // Close the serial port
    close(uart_fd);

    return EXIT_SUCCESS;
}

