    if (!gpio18_line || !gpio23_line || !gpio24_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        // Release previously acquired lines
        if(gpio18_line) gpiod_line_release(gpio18_line);
        if(gpio23_line) gpiod_line_release(gpio23_line);
        if(gpio24_line) gpiod_line_release(gpio24_line);
