int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_count = 0;
    int i, j;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30);
    gpioSetMode(gpio, PI_INPUT);

    /* Wait for the DHT22 to pull the line low */
    int timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    timeout = 0;
    while (gpioRead(gpio) == 0) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) return -1; // Timeout
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio) == 1) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) return -1; // Timeout
        }
        long end = gpioTick();

        if ((end - start) > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    if ((data[0] + data[1] + data[2] + data[3]) & 0xFF != data[4]) {
        return -2; // Checksum failure
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

