float adc_to_temperature(int adc_value);
int publish_temperature(float temperature);
void signal_handler(int signum);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to temperature (Celsius)
float adc_to_temperature(int adc_value) {
    if (adc_value < ADC_MIN || adc_value > ADC_MAX) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1000.0; // Indicate an error
    }

    // Linear approximation: 0°C = 10 bits, 50°C = 0 bits
    float temperature = 50.0 - ((float)adc_value / 1023.0) * 40.0;

    return temperature;
}

// Function to publish temperature reading to MQTT broker
int publish_temperature(float temperature) {
    char payload[50];
    snprintf(payload, sizeof(payload), "%.2f", temperature);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: MQTT publish failed: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    printf("Published temperature: %.2f\n", temperature);
    return 0;
}

