        close(fd);
        return 1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        close(fd);
        return 1;
    }

    // 5. Map the buffers
    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(fd);
            free(buffers);
            return 1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[n_buffers].start == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            free(buffers);
            return 1;
        }
    }

    // 6. Queue the buffers
    for (int i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            close(fd);
            for (int j = 0; j < n_buffers; ++j) {
                munmap(buffers[j].start, buffers[j].length);
            }
            free(buffers);
            return 1;
        }
    }

    // 7. Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        close(fd);
        for (int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return 1;
    }

    // 8. Capture an image (read from the first buffer)
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        close(fd);
        for (int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return 1;
    }

    // 9. Save the image to a file
    snprintf(filename, sizeof(filename), "image_%dx%d.yuyv", IMAGE_WIDTH, IMAGE_HEIGHT);
    fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening file");
        close(fd);
        for (int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return 1;
    }

    fwrite(buffers[buf.index].start, buf.bytesused, 1, fp);
    fclose(fp);

    // 10. Requeue the buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error requeuing buffer");
        close(fd);
        for (int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return 1;
    }

    // 11. Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        close(fd);
        for (int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return 1;
    }

    // 12. Unmap buffers
    for (int i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            perror("Error unmapping buffer");
        }
    }

    // 13. Free buffer array
    free(buffers);

    // 14. Close the device
    close(fd);

    printf("Image saved as %s\n", filename);
    return 0;
}

