    }

    *width = fmt.fmt.pix.width;
    *height = fmt.fmt.pix.height;

    return 0;
}

static int capture_frame(FILE *fp)
{
    struct v4l2_buffer buf;
    struct timeval tv;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
        fprintf(stderr, "VIDIOC_DQBUF error\n");
        return -1;
    }

    frame_count++;

    gettimeofday(&tv, NULL);
    fprintf(fp, "%ld.%06ld: Frame %d\n", tv.tv_sec, tv.tv_usec, frame_count);
    fflush(fp);

    if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
        fprintf(stderr, "VIDIOC_QBUF error\n");
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    unsigned int i;

    if (fd != -1) {
        for (i = 0; i < n_buffers; ++i) {
            if (buffers && buffers[i].start) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
        buffers = NULL;

        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
        fd = -1;
    }

    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
}

int main(void)
{
    unsigned int width, height;
    char filename[64];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (0 != init_device(DEVICE_NAME, &width, &height)) {
        fprintf(stderr, "Failed to initialize device\n");
        return EXIT_FAILURE;
    }

    snprintf(filename, sizeof(filename), "frame_%dx%d_%04d.yuyv", width, height, (int)time(NULL));

    fp = fopen(filename, "w");
    if (NULL == fp) {
        fprintf(stderr, "Failed to open output file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(fp, "Frame sequence and timestamp\n");

    while (!stop_flag) {
        if (capture_frame(fp) < 0) {
            fprintf(stderr, "Capture failed, exiting...\n");
            break;
        }
        usleep(100000); // 0.1 seconds
    }

    fprintf(stderr, "Captured %d frames in %s\n", frame_count, filename);

    cleanup();

    return EXIT_SUCCESS;
}

