    if (gpio_status != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode: %d\n", GPIO_23, gpio_status);
        gpioTerminate();
        return 1;
    }

    gpio_status = gpioSetMode(GPIO_24, PI_OUTPUT);
    if (gpio_status != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode: %d\n", GPIO_24, gpio_status);
        gpioTerminate();
        return 1;
    }

    /* Set PWM frequency to 1000 Hz */
    gpioSetPWMfrequency(GPIO_18, 1000);
    gpioSetPWMfrequency(GPIO_23, 1000);
    gpioSetPWMfrequency(GPIO_24, 1000);

    /* Set PWM range to 255 */
    gpioSetPWMrange(GPIO_18, 255);
    gpioSetPWMrange(GPIO_23, 255);
