#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define MAX_DISTANCE 400     // cm
#define TIMEOUT_US 50000      // 50ms timeout

// Global variables
static volatile int echo_start_time = 0;
static volatile int echo_end_time = 0;
static volatile int echo_received = 0;
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static int running = 1;

// Function prototypes
int init_gpio(void);
void trigger_pulse(void);
void echo_callback(int gpiod_line, int event);
double calculate_distance(int pulse_width);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        running = 0;
    }
}

// Initialize GPIO lines
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "ultrasonic_trigger", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "ultrasonic_echo", 0) < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    // Set up interrupt callback for echo pin
    if (gpiod_line_request_rising_edge_events(echo_line, "ultrasonic_echo_rising") < 0) {
        perror("Error requesting rising edge events for echo line");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }
    if (gpiod_line_request_falling_edge_events(echo_line, "ultrasonic_echo_falling") < 0) {
        perror("Error requesting falling edge events for echo line");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    return 0;
}

// Generate a 10us trigger pulse
void trigger_pulse(void) {
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger line high");
    }
    usleep(10); // 10us pulse
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger line low");
    }
}

// Callback function for echo pin events
void echo_callback(int gpiod_line, int event) {
    struct timespec ts;

    if (event == GPIOD_LINE_EVENT_RISING_EDGE) {
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            perror("clock_gettime");
            return;
        }
        echo_start_time = ts.tv_sec * 1000000 + ts.tv_nsec / 1000; // Microseconds
        echo_received = 1; // Indicate rising edge received
    } else if (event == GPIOD_LINE_EVENT_FALLING_EDGE) {
        if (echo_received == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
                perror("clock_gettime");
                return;
            }
            echo_end_time = ts.tv_sec * 1000000 + ts.tv_nsec / 1000; // Microseconds
        }
    }
}

// Calculate distance in centimeters
double calculate_distance(int pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("Ultrasonic sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_start_time = 0;
        echo_end_time = 0;
        echo_received = 0;

        // Trigger the sensor
        trigger_pulse();

        // Wait for echo or timeout
        int timeout_count = 0;
        while (echo_end_time == 0 && timeout_count < TIMEOUT_US) {
            usleep(1); // Check every microsecond
            timeout_count++;
        }

        if (echo_end_time == 0) {
            fprintf(stderr, "Timeout waiting for echo. Retrying.\n");
            usleep(100000); // Wait before retrying
            continue;
        }

        // Calculate pulse width
        int pulse_width = echo_end_time - echo_start_time;

        // Check for valid pulse width
        if (pulse_width < 0 || pulse_width > MAX_DISTANCE * 2) {
            fprintf(stderr, "Invalid pulse width: %d. Ignoring.\n", pulse_width);
            usleep(100000); // Wait before retrying
            continue;
        }

        // Calculate distance
        double distance = calculate_distance(pulse_width);

        // Report distance
        printf("Distance: %.2f cm\n", distance);

        usleep(100000); // Delay between readings
    }

    // Cleanup GPIO
    cleanup_gpio();

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

