#include <stdint.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the MPU6050
int16_t read_word_2c(int fd, uint8_t reg) {
    int16_t high, low, value;

    high = ioctl(fd, I2C_SLAVE, reg);
    if (high < 0) {
        perror("Failed to acquire bus access");
        return -1;
    }

    low = ioctl(fd, I2C_SLAVE, reg + 1);
    if (low < 0) {
        perror("Failed to acquire bus access");
        return -1;
    }

    value = (high << 8) | low;
    return value;
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // I2C device file

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep mode bit)
    uint8_t wake_up_value = 0x00;
    if (write(i2c_fd, &wake_up_value, 1) != 1) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer data
        int16_t accel_x = read_word_2c(i2c_fd, ACCEL_XOUT_H);
        int16_t accel_y = read_word_2c(i2c_fd, ACCEL_YOUT_H);
        int16_t accel_z = read_word_2c(i2c_fd, ACCEL_ZOUT_H);

        if (accel_x == -1 || accel_y == -1 || accel_z == -1) {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
            usleep(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Print accelerometer data
        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);

        // Wait 0.1 seconds
        usleep(100000);
    }

    return 0;
}

