// Function to read data from DHT22 sensor
int read_dht22(float *temperature, float *humidity)
{
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_count = 0;
    int i, j;

    gpioSetMode(DHT22_PIN, PI_OUTPUT);
    gpioWrite(DHT22_PIN, 0);
    gpioDelay(1);
    gpioWrite(DHT22_PIN, 1);
    gpioDelay(30); // Changed from 40 to 30

    gpioSetMode(DHT22_PIN, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout_start = gpioTick();
    while (gpioRead(DHT22_PIN) == 1) {
        if (gpioTick() - timeout_start > DHT22_TIMEOUT) {
            fprintf(stderr, "DHT22: Timeout waiting for start signal\n");
            return -1; // Timeout
        }
    }

    // Wait for the DHT22 to pull the line high
    timeout_start = gpioTick();
    while (gpioRead(DHT22_PIN) == 0) {
        if (gpioTick() - timeout_start > DHT22_TIMEOUT) {
            fprintf(stderr, "DHT22: Timeout waiting for end of start signal\n");
            return -1; // Timeout
        }
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++)
    {
        // Wait for the line to go low
        timeout_start = gpioTick();
        while (gpioRead(DHT22_PIN) == 1) {
            if (gpioTick() - timeout_start > DHT22_TIMEOUT) {
                fprintf(stderr, "DHT22: Timeout waiting for data bit low\n");
                return -1; // Timeout
            }
        }

        // Measure the length of the high pulse
        pulse_count = 0;
        timeout_start = gpioTick();
        while (gpioRead(DHT22_PIN) == 0) {
            if (gpioTick() - timeout_start > DHT22_TIMEOUT) {
                fprintf(stderr, "DHT22: Timeout waiting for data bit high\n");
                return -1; // Timeout
            }
        }

        pulse_count = gpioTick() - timeout_start;

        // Determine if the bit is a 0 or a 1 based on the pulse length
        data[i / 8] <<= 1;
        if (pulse_count > 40) // Adjusted threshold
        {
            data[i / 8] |= 1;
        }
    }

    // Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4])
    {
        fprintf(stderr, "DHT22: Checksum error\n");
        return -1; // Checksum error
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80)
    {
        *temperature = -*temperature;
    }

    return 0; // Success
}

