#define SHT31_ADDR 0x44
#define MEASURE_CMD 0x2C06

int i2c_fd;

void signal_handler(int sig);
int read_sht31(float *temperature, float *humidity);

int main() {
    float temperature, humidity;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        if (read_sht31(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read SHT31 data.\n");
        }
        sleep(5);
    }

    return 0;
}

void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully.\n", sig);
    close(i2c_fd);
    exit(0);
}

int read_sht31(float *temperature, float *humidity) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t data[6];

    // Send measurement command
    if (write(i2c_fd, cmd, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement to complete (typical conversion time is 10ms)
    usleep(20000); // 20ms

    // Read 6 bytes of data
    if (read(i2c_fd, data, 6) != 6) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Convert data to temperature and humidity
    int temp_raw = (data[0] << 8) | data[1];
    int hum_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    // Validate data
    if (*temperature < -40.0 || *temperature > 125.0 || *humidity < 0.0 || *humidity > 100.0) {
        fprintf(stderr, "Invalid sensor data: Temperature=%.2f, Humidity=%.2f\n", *temperature, *humidity);
        return -1;
    }

    return 0;
}

