    // Release GPIO lines
    for (int i = 0; i < 10; i++) {
        if (gpio_state.lines[i]) {
            gpiod_line_release(gpio_state.lines[i]);
        }
    }

    // Close the GPIO chip
    if (gpio_state.chip) {
        gpiod_chip_close(gpio_state.chip);
    }

    exit(0);
}

// Function to set the state of a GPIO pin
int set_gpio_state(int pin, int state) {
    int line_index = -1;
    for (int i = 0; i < 10; i++) {
        if (gpio_state.lines[i] && gpiod_line_get_number(gpio_state.lines[i]) == pin) {
            line_index = i;
            break;
        }
    }

    if (line_index == -1) {
        fprintf(stderr, "Error: GPIO line %d not found.\n", pin);
        return -1;
    }

    int ret = gpiod_line_set_value(gpio_state.lines[line_index], state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d to %d: %s\n", pin, state, strerror(errno));
        return -1;
    }

    return 0;
}

