        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_LINE_2, strerror(errno));
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO line 1 HIGH
        if (gpiod_line_set_value(line1, 1) < 0) {
            fprintf(stderr, "Error setting GPIO line %d HIGH: %s\n", GPIO_LINE_1, strerror(errno));
            break; // Exit loop on error
        }
        printf("GPIO line %d HIGH\n", GPIO_LINE_1);
        sleep(1);

        // Set GPIO line 1 LOW
        if (gpiod_line_set_value(line1, 0) < 0) {
            fprintf(stderr, "Error setting GPIO line %d LOW: %s\n", GPIO_LINE_1, strerror(errno));
            break; // Exit loop on error
        }
        printf("GPIO line %d LOW\n", GPIO_LINE_1);
