        return 1;
    }

    // Get GPIO line for GPIO 17
    gpio_line_2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!gpio_line_2) {
        perror("Error getting GPIO line 17");
        gpiod_line_release(gpio_line_1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line 2 as output
    ret = gpiod_line_request_output(gpio_line_1, "gpio_output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 2 as output");
        gpiod_line_release(gpio_line_1);
        gpiod_line_release(gpio_line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line 17 as output
    ret = gpiod_line_request_output(gpio_line_2, "gpio_output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17 as output");
        gpiod_line_release(gpio_line_1);
        gpiod_line_release(gpio_line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Read initial states
    current_state_1 = gpiod_line_get_value(gpio_line_1);
    current_state_2 = gpiod_line_get_value(gpio_line_2);

    printf("Initial state: GPIO %d = %d, GPIO %d = %d\n", GPIO_PIN_1, current_state_1, GPIO_PIN_2, current_state_2);

    // Set up sleep time for 60 seconds
    sleep_time.tv_sec = 60;
    sleep_time.tv_nsec = 0;

    // Main loop
    while (1) {
        // Toggle GPIO 2
        ret = gpiod_line_set_value(gpio_line_1, !current_state_1);
        if (ret < 0) {
            perror("Error setting GPIO line 2 value");
            break;
        }
        current_state_1 = !current_state_1;

        // Set GPIO 17 to the current state of GPIO 2
        ret = gpiod_line_set_value(gpio_line_2, current_state_2);
