        // Print the current state
        printf("GPIO %d = %d, GPIO %d = %d\n", GPIO_PIN_1, current_state_1, GPIO_PIN_2, current_state_2);

        // Sleep for 60 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
            break;
        }
    }

    // Release GPIO lines and close chip before exiting
    signal_handler(SIGINT);

