    if (gpiod_line_request(gpio_c_line, &config, 0) < 0) {
        perror("Error requesting GPIO C for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO states
        struct timespec delay = {0, 100000000}; // 100ms
        if (gpiod_line_set_value(gpio_a_line, 0) < 0) {
            perror("Error setting GPIO A value");
            break;
        }
        if (gpiod_line_set_value(gpio_b_line, 1) < 0) {
            perror("Error setting GPIO B value");
            break;
        }
        if (gpiod_line_set_value(gpio_c_line, 0) < 0) {
            perror("Error setting GPIO C value");
            break;
        }
        nanosleep(&delay, NULL);

        if (gpiod_line_set_value(gpio_a_line, 1) < 0) {
            perror("Error setting GPIO A value");
            break;
        }
        if (gpiod_line_set_value(gpio_b_line, 0) < 0) {
            perror("Error setting GPIO B value");
            break;
        }
        if (gpiod_line_set_value(gpio_c_line, 1) < 0) {
            perror("Error setting GPIO C value");
            break;
        }
        nanosleep(&delay, NULL);

        if (gpiod_line_set_value(gpio_a_line, 0) < 0) {
            perror("Error setting GPIO A value");
            break;
        }
        if (gpiod_line_set_value(gpio_b_line, 1) < 0) {
            perror("Error setting GPIO B value");
            break;
        }
        if (gpiod_line_set_value(gpio_c_line, 0) < 0) {
            perror("Error setting GPIO C value");
            break;
        }
