#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    int ret;
    int current_value;
    int new_value;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Read current value
        current_value = gpiod_line_get_value(line);
        if (current_value < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        // Toggle the value
        new_value = (current_value == 0) ? 1 : 0;

        // Set the new value
        ret = gpiod_line_set_value(line, new_value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        // Report the state
        printf("GPIO %d: %s\n", GPIO_PIN, (new_value == 1) ? "HIGH" : "LOW");

        // Wait for 1 second
        sleep(1);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

