        return 1;
    }

    // Configure the GPIO line request
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio-example";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    // Request GPIO line 18 as output
    ret = gpiod_line_request(gpio_line_1, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_PIN_1, strerror(errno));
