#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 18
#define NUM_CYCLES 3
#define DELAY_US 5000 // 0.005 seconds

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    int i, gpio_status;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("Setting GPIO %d to the following colors:\n", GPIO_PIN);

    for (i = 0; i < NUM_CYCLES && !terminate; ++i) {
        // Red
        gpio_status = gpioWrite(GPIO_PIN, 1); // High
        if (gpio_status != 0) {
            fprintf(stderr, "Error writing to GPIO %d (Red): %d\n", GPIO_PIN, gpio_status);
            gpioTerminate();
            return 1;
        }
        gpioDelay(DELAY_US);

        // Green
        gpio_status = gpioWrite(GPIO_PIN, 0); // Low
        if (gpio_status != 0) {
            fprintf(stderr, "Error writing to GPIO %d (Green): %d\n", GPIO_PIN, gpio_status);
            gpioTerminate();
            return 1;
        }
        gpioDelay(DELAY_US);

        // Blue
        gpio_status = gpioWrite(GPIO_PIN, 1); // High
        if (gpio_status != 0) {
            fprintf(stderr, "Error writing to GPIO %d (Blue): %d\n", GPIO_PIN, gpio_status);
            gpioTerminate();
            return 1;
        }
        gpioDelay(DELAY_US);
    }

    printf("Cleaning up and exiting...\n");
    gpioTerminate();
    return 0;
}

