float read_temperature() {
    char device_path[256];
    snprintf(device_path, sizeof(device_path), "%s%s/%s", W1_DEVICES_DIR, device_id, W1_SLAVE_FILE);

    FILE *fp = fopen(device_path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", device_path, strerror(errno));
        return -273.15; // Return absolute zero as error indicator
    }

