#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define MOTION_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 50000      // 50ms timeout

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
void trigger_pulse();
float get_distance();
void motion_detected();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure distance using the HC-SR04
float get_distance() {
    long long start_tick, end_tick, diff_tick;

    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Wait for echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pin did not go high within timeout.\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1);
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pin did not go low within timeout.\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to handle motion detection
void motion_detected() {
    float distance = get_distance();

    if (distance > 0) {
        printf("Motion detected! Distance: %.2f cm\n", distance);
    } else {
        printf("Motion detected! Distance measurement failed.\n");
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(MOTION_PIN, PI_INPUT);
    gpioSetPullUpDown(MOTION_PIN, PI_PUD_DOWN); // Optional: Pull-down resistor

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (gpioRead(MOTION_PIN) == 1) {
            motion_detected();
        }
        gpioDelay(100); // Check every 100ms
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

