static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int ret;
    int current_value = -1; // Initialize to an invalid value

    // Register signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT) failed");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM) failed");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Read current value (if needed)
        if (current_value == -1) {
            ret = gpiod_line_get_value(line);
            if (ret < 0) {
                fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
                break; // Exit loop on error
            }
            current_value = ret;
        }

        // Print current value
        printf("GPIO %d: %s\n", GPIO_PIN, (current_value == 1) ? "HIGH" : "LOW");

        // Toggle value (simulated)
        current_value = !current_value;

        // Apply new value
        ret = gpiod_line_set_value(line, current_value);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        // Wait 1 second
        sleep(1);
    }

    // Cleanup
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return (keep_running) ? EXIT_SUCCESS : EXIT_FAILURE;
}

