        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        // Release previously acquired lines
        if(gpio17_line) gpiod_line_release(gpio17_line);
        if(gpio23_line) gpiod_line_release(gpio23_line);
        if(gpio24_line) gpiod_line_release(gpio24_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure GPIO lines for output
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(gpio17_line, &config, 0);
