#include <unistd.h>
#include <pigpio.h>

#define PWM_GPIO 4
#define LED_GPIO_1 17
#define LED_GPIO_2 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    int pwm_value = 0;
    int led_state_1 = 0;
    int led_state_2 = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetMode(LED_GPIO_1, PI_OUTPUT);
    gpioSetMode(LED_GPIO_2, PI_OUTPUT);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        // PWM Output
        gpioPWM(PWM_GPIO, pwm_value);

        // LED Output
        gpioWrite(LED_GPIO_1, led_state_1);
        gpioWrite(LED_GPIO_2, led_state_2);

        // Report State
        printf("PWM: %d, LED1: %d, LED2: %d\n", pwm_value, led_state_1, led_state_2);

        // Validity Check (Example: PWM within 0-255 range)
        if (pwm_value < 0 || pwm_value > 255) {
            fprintf(stderr, "Error: Invalid PWM value: %d\n", pwm_value);
        }

        // Increment Values
        pwm_value = (pwm_value + 5) % 256; // Cycle through 0-255
        led_state_1 = (led_state_1 + 1) % 2; // Cycle through 0 and 1
        led_state_2 = (led_state_2 + 1) % 2; // Cycle through 0 and 1

        gpioDelay(100000); // 0.1 seconds
    }

    // Cleanup
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioWrite(LED_GPIO_1, 0); // Turn off LED 1
    gpioWrite(LED_GPIO_2, 0); // Turn off LED 2
    gpioTerminate();

    return 0;
}

