            gpiod_chip_close(chip);
            return 1;
        }

        usleep(50000); // 0.05 seconds
    }

    // Release GPIO lines
    gpiod_line_release(gpio_line_1);
    gpiod_line_release(gpio_line_2);
    gpiod_line_release(gpio_line_3);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 17
#define DHT22_PIN 27

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    int pwm_value = 0;
    int dht22_data[5] = {0, 0, 0, 0, 0};
    int dht22_laststate = 1; // Assume initial state is HIGH
    int dht22_counter = 0;
    int dht22_bit = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetMode(DHT22_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);

    printf("PWM output on GPIO %d, DHT22 data on GPIO %d. Press Ctrl+C to exit.\n", PWM_PIN, DHT22_PIN);

    while (!terminate) {
        // DHT22 data acquisition
        dht22_counter = 0;
        dht22_bit = 0;
        dht22_laststate = 1; // Reset last state

        // Send start signal
        gpioSetMode(DHT22_PIN, PI_OUTPUT);
        gpioWrite(DHT22_PIN, 0);
        gpioDelay(1); // > 1ms
        gpioWrite(DHT22_PIN, 1);
        gpioDelay(30); // 20-40us
        gpioSetMode(DHT22_PIN, PI_INPUT);

        // Read data
        for (int i = 0; i < 40; i++) {
            int counter = 0;
            while (gpioRead(DHT22_PIN) == dht22_laststate) {
                counter++;
                gpioDelay(1); // Delay 1 us
                if (counter == 255) {
                    break;
                }
            }
            dht22_laststate = gpioRead(DHT22_PIN);

            if (counter == 255) break;

            // Ignore first 3 transitions
            if ((i >= 4) && (i % 2 == 0)) {
                dht22_data[dht22_bit / 8] <<= 1;
                if (counter > 16) {
                    dht22_data[dht22_bit / 8] |= 1;
                }
                dht22_bit++;
            }
        }

        // Verify checksum
        if ((dht22_data[0] + dht22_data[1] + dht22_data[2] + dht22_data[3]) & 0xFF == dht22_data[4]) {
            float temperature = (float)((dht22_data[2] & 0x7F) * 256 + dht22_data[3]) / 10.0;
            if (dht22_data[2] & 0x80) {
                temperature *= -1;
            }

            float humidity = (float)(dht22_data[0] * 256 + dht22_data[1]) / 10.0;

            printf("Temperature: %.1f°C, Humidity: %.1f%%\n", temperature, humidity);
        } else {
            fprintf(stderr, "DHT22 Checksum error\n");
        }

        // PWM output
        gpioPWM(PWM_PIN, pwm_value);
        printf("PWM Value: %d\n", pwm_value);

        // Increment PWM value
        pwm_value = (pwm_value + 5) % 256; // Cycle through 0-255

        gpioDelay(500); // Delay 500ms
    }

    // Cleanup
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the GPIO pins to control
#define GPIO_PINS {4, 17, 22, 23, 24, 25, 27}

// Structure to hold GPIO chip and line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[7]; // Assuming a maximum of 7 GPIO pins
} gpio_state_t;

// Global variable to store the GPIO state
gpio_state_t gpio_state = {0};

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < 7; i++) {
        if (gpio_state.lines[i]) {
            gpiod_line_release(gpio_state.lines[i]);
        }
    }

    // Close the GPIO chip
    if (gpio_state.chip) {
        gpiod_chip_close(gpio_state.chip);
    }

    exit(0);
}

// Function to set the state of a GPIO pin
int set_gpio_state(gpio_state_t *gpio_state, int pin, int value) {
    int line_index = -1;
    for (int i = 0; i < 7; i++) {
        if (gpio_state->lines[i] && gpiod_line_get_number(gpio_state->lines[i]) == pin) {
            line_index = i;
            break;
        }
    }

    if (line_index == -1) {
        fprintf(stderr, "Error: GPIO line %d not found in GPIO state.\n", pin);
        return -1;
    }

    int ret = gpiod_line_set_value(gpio_state->lines[line_index], value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d to %d: %s\n", pin, value, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to report the state of all GPIO pins
void report_gpio_state(gpio_state_t *gpio_state) {
    printf("GPIO State: ");
    for (int i = 0; i < 7; i++) {
        if (gpio_state->lines[i]) {
            int value = gpiod_line_get_value(gpio_state->lines[i]);
            printf("%d=%d ", gpiod_line_get_number(gpio_state->lines[i]), value);
        } else {
            printf("%d=N/A ", gpiod_line_get_number(gpio_state->lines[i]));
        }
    }
    printf("\n");
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    gpio_state.chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_state.chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    int pins[] = GPIO_PINS;
    for (int i = 0; i < 7; i++) {
        gpio_state.lines[i] = gpiod_chip_get_line(gpio_state.chip, pins[i]);
        if (!gpio_state.lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", pins[i], strerror(errno));
            // Release previously acquired lines before exiting
            for (int j = 0; j < i; j++) {
                gpiod_line_release(gpio_state.lines[j]);
            }
            gpiod_chip_close(gpio_state.chip);
            return 1;
        }

        // Request the line for output
        int ret = gpiod_line_request_output(gpio_state.lines[i], "gpio_control", 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", pins[i], strerror(errno));
            // Release previously acquired lines before exiting
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(gpio_state.lines[j]);
            }
            gpiod_chip_close(gpio_state.chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        // Set GPIO states
        for (int i = 0; i < 7; i++) {
            if (gpio_state.lines[i]) {
                // Toggle the state of each GPIO line
                int current_value = gpiod_line_get_value(gpio_state.lines[i]);
                int new_value = (current_value == 0) ? 1 : 0;
                if (set_gpio_state(&gpio_state, gpiod_line_get_number(gpio_state.lines[i]), new_value) != 0) {
                    // Error setting GPIO, exit
                    signal_handler(SIGINT); // Simulate signal to cleanup
                    return 1;
                }
            }
        }

        // Report GPIO state
        report_gpio_state(&gpio_state);

        // Wait for 0.5 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

