#define GPIOCHIP "gpiochip0"
#define GPIO17 17
#define GPIO18 18

static struct gpiod_chip *chip;
static struct gpiod_line *gpio17_line;
static struct gpiod_line *gpio18_line;
static volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    int ret;
    unsigned int value;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get GPIO 17 line
    gpio17_line = gpiod_chip_get_line(chip, GPIO17);
    if (!gpio17_line) {
        perror("gpiod_chip_get_line (GPIO17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get GPIO 18 line
    gpio18_line = gpiod_chip_get_line(chip, GPIO18);
    if (!gpio18_line) {
        perror("gpiod_chip_get_line (GPIO18)");
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 17 as output
    ret = gpiod_line_request_output(gpio17_line, "gpio-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO17)");
        gpiod_line_release(gpio18_line);
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 18 as output
    ret = gpiod_line_request_output(gpio18_line, "gpio-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO18)");
        gpiod_line_release(gpio17_line);
        gpiod_line_release(gpio18_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Toggle GPIO 17
        value = !value; // Toggle the value
        ret = gpiod_line_set_value(gpio17_line, value);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO17)");
            break;
        }

        // Toggle GPIO 18
        value = !value; // Toggle the value
        ret = gpiod_line_set_value(gpio18_line, value);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO18)");
            break;
        }

        printf("GPIO17: %d, GPIO18: %d\n", value, value);
        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpiod_line_release(gpio17_line);
    gpiod_line_release(gpio18_line);
    gpiod_chip_close(chip);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

