    gpio_line_1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    gpio_line_2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    gpio_line_3 = gpiod_chip_get_line(chip, GPIO_PIN_3);

    if (!gpio_line_1 || !gpio_line_2 || !gpio_line_3) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        // Release any previously acquired lines
        if (gpio_line_1) gpiod_line_release(gpio_line_1);
        if (gpio_line_2) gpiod_line_release(gpio_line_2);
        if (gpio_line_3) gpiod_line_release(gpio_line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines for output
    ret = gpiod_line_request_output(gpio_line_1, "gpio_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_PIN_1, strerror(errno));
        goto cleanup;
    }
    ret = gpiod_line_request_output(gpio_line_2, "gpio_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_PIN_2, strerror(errno));
        goto cleanup;
    }
    ret = gpiod_line_request_output(gpio_line_3, "gpio_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_PIN_3, strerror(errno));
        goto cleanup;
    }

    // Main loop
    while (1) {
        // Set the GPIO output values
        ret = gpiod_line_set_value(gpio_line_1, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_PIN_1, strerror(errno));
            goto cleanup;
        }
        ret = gpiod_line_set_value(gpio_line_2, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_PIN_2, strerror(errno));
            goto cleanup;
        }
        ret = gpiod_line_set_value(gpio_line_3, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_PIN_3, strerror(errno));
            goto cleanup;
        }

        // Print the current state
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, (int)gpiod_line_get_value(gpio_line_1), GPIO_PIN_2, (int)gpiod_line_get_value(gpio_line_2), GPIO_PIN_3, (int)gpiod_line_get_value(gpio_line_3));

        // Wait for 0.1 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

cleanup:
    // Release GPIO lines
    if (gpio_line_1) {
        gpiod_line_release(gpio_line_1);
    }
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }
    if (gpio_line_3) {
        gpiod_line_release(gpio_line_3);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 1;
}

