#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define DHT22_GPIO 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_count = 0;
    int i, j;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30);
    gpioSetMode(gpio, PI_INPUT);

    for (i = 0; i < 85; i++) {
        int count = 0;
        while (gpioRead(gpio) == 0 && count++ < 1000) {
            gpioDelay(1);
        }
        count = 0;
        while (gpioRead(gpio) == 1 && count++ < 1000) {
            gpioDelay(1);
        }
        pulse_count += count;

        if (pulse_count > 40) {
            data[bit_count / 8] |= (1 << (7 - (bit_count % 8)));
        }
        bit_count++;
        pulse_count = 0;
    }

    if (bit_count != 80) {
        fprintf(stderr, "DHT22: Invalid bit count: %d\n", bit_count);
        return -1;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "DHT22: Checksum failure\n");
        return -1;
    }

    *humidity = (float)(((data[0] << 8) + data[1])) / 10.0;
    *temperature = (float)(((data[2] << 8) + data[3])) / 10.0;
    if (*temperature > 125) {
        *temperature = *temperature - 256;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    float temperature, humidity;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    while (!terminate) {
        if (read_dht22(DHT22_GPIO, &temperature, &humidity) == 0) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s - Temperature: %.1f°C, Humidity: %.1f%%\n", timestamp, temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read DHT22 data\n");
        }
        sleep(60);
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

