    gpioSetMode(GPIO_18, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        // State 1
        gpioPWM(GPIO_17, 128);
        gpioPWM(GPIO_18, 128);
        gpioPWM(GPIO_27, 128);
        printf("GPIO 17: 128, GPIO 18: 128, GPIO 27: 128\n");
        sleep(1);

        // State 0
        gpioPWM(GPIO_17, 0);
        gpioPWM(GPIO_18, 0);
        gpioPWM(GPIO_27, 0);
        printf("GPIO 17: 0, GPIO 18: 0, GPIO 27: 0\n");
        sleep(1);
    }

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

