struct gpiod_chip *chip;
struct gpiod_line *line_17;
struct gpiod_line *line_22;
struct gpiod_line *line_23;
struct gpiod_line *line_27;

// Function prototypes
int set_gpio_output(struct gpiod_line *line, int value);
int get_gpio_output(struct gpiod_line *line);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");

    // Release GPIO lines
    if (line_17) {
        gpiod_line_release(line_17);
    }
    if (line_22) {
        gpiod_line_release(line_22);
    }
    if (line_23) {
        gpiod_line_release(line_23);
    }
    if (line_27) {
        gpiod_line_release(line_27);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set the output value of a GPIO line
int set_gpio_output(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to get the output value of a GPIO line
int get_gpio_output(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO value: %s\n", strerror(-value));
        return -1;
    }
    return value;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the line numbers for each GPIO pin
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    line_22 = gpiod_chip_get_line(chip, GPIO_22);
    line_23 = gpiod_chip_get_line(chip, GPIO_23);
    line_27 = gpiod_chip_get_line(chip, GPIO_27);

    if (!line_17 || !line_22 || !line_23 || !line_27) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup(0);
        return 1;
    }

    // Request the lines as outputs
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio-output-control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line_17, &config, 0) < 0 ||
        gpiod_line_request(line_22, &config, 0) < 0 ||
        gpiod_line_request(line_23, &config, 0) < 0 ||
        gpiod_line_request(line_27, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        cleanup(0);
        return 1;
    }

    // Main loop
    while (1) {
        // Get the current state of each GPIO line
        int value_17 = get_gpio_output(line_17);
        int value_22 = get_gpio_output(line_22);
        int value_23 = get_gpio_output(line_23);
        int value_27 = get_gpio_output(line_27);

        if (value_17 < 0 || value_22 < 0 || value_23 < 0 || value_27 < 0) {
            fprintf(stderr, "Error getting GPIO value, exiting...\n");
            cleanup(0);
            return 1;
        }

        // Print the current state of each GPIO line
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
               GPIO_17, value_17, GPIO_22, value_22, GPIO_23, value_23, GPIO_27, value_27);

        // Toggle the state of GPIO 17 and GPIO 22
        if (set_gpio_output(line_17, !value_17) < 0 ||
            set_gpio_output(line_22, !value_22) < 0) {
            fprintf(stderr, "Error setting GPIO value, exiting...\n");
            cleanup(0);
            return 1;
        }

        // Wait for 0.1 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

