#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <string.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

int spi_fd;

// Function to initialize the SPI interface
int spi_init()
{
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read data from the MAX31855
int read_max31855(uint8_t *data)
{
    struct spi_ioc_transfer transfer = {
        .tx_buf = 0, // Read only
        .rx_buf = (unsigned long)data,
        .len = 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    return 0;
}

// Function to parse the MAX31855 data
int parse_max31855(uint8_t *data, float *internal_temp, float *thermocouple_temp, int *fault)
{
    // Check for fault bits
    *fault = (data[3] >> 0) & 0x01; // LSB of fault bit
    if (*fault) {
        fprintf(stderr, "MAX31855 Fault: %x\n", data[3]);
        return -1; // Indicate fault
    }

    // Extract thermocouple temperature
    int16_t thermocouple_raw = ((data[0] << 8) | data[1]) >> 2;
    *thermocouple_temp = thermocouple_raw * 0.25;

    // Extract internal temperature
    int16_t internal_raw = ((data[2] << 8) | data[3]) >> 4;
    *internal_temp = internal_raw * 0.0625;

    // Check for valid temperature ranges
    if (*thermocouple_temp < -100.0 || *thermocouple_temp > 1000.0 || *internal_temp < -40.0 || *internal_temp > 125.0) {
        fprintf(stderr, "Temperature out of range\n");
        return -1; // Indicate out-of-range value
    }

    return 0;
}

// Function to close the SPI device
void spi_close()
{
    close(spi_fd);
}

int main()
{
    uint8_t data[4];
    float internal_temp, thermocouple_temp;
    int fault;

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Read data from MAX31855
    if (read_max31855(data) < 0) {
        fprintf(stderr, "Failed to read MAX31855 data\n");
        spi_close();
        return 1;
    }

    // Parse the data
    if (parse_max31855(data, &internal_temp, &thermocouple_temp, &fault) < 0) {
        fprintf(stderr, "Failed to parse MAX31855 data\n");
        spi_close();
        return 1;
    }

    // Print the results
    printf("Thermocouple Temp: %.2f C, Internal Temp: %.2f C, Fault: %d\n", thermocouple_temp, internal_temp, fault);

    // Close SPI device
    spi_close();

    return 0;
}

