        usleep(100000); // 0.1 seconds

        // Set GPIO line 18 low
        if (gpiod_line_set_value(line_18, 0) < 0) {
            perror("Error setting GPIO line 18 low");
            break;
        }
        printf("GPIO 18: LOW\n");
        usleep(100000); // 0.1 seconds
    }

    // Release GPIO lines and close chip (in case of error)
    gpiod_line_release(line_17);
    gpiod_line_release(line_18);
    gpiod_chip_close(chip);

    return 1;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 50000      // 50ms timeout

// Global variables
volatile int pulse_start = 0;
volatile int pulse_end = 0;
volatile int timeout_flag = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
    } else if (level == 0) {
        pulse_end = tick;
    } else if (level == PI_TIMEOUT) {
        timeout_flag = 1;
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("HC-SR04 distance sensor\n");

    while (1) {
        // Generate trigger pulse
        trigger_pulse();

        // Wait for echo or timeout
        int start_time = gpioTick();
        while (pulse_start == 0 && (gpioTick() - start_time) < TIMEOUT_US) {
            gpioDelay(1); // Small delay to prevent busy-waiting
        }

        if (pulse_start == 0) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            timeout_flag = 1;
        }

        start_time = gpioTick();
        while (pulse_end == 0 && (gpioTick() - start_time) < TIMEOUT_US) {
            gpioDelay(1);
        }

        if (pulse_end == 0) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            timeout_flag = 1;
        }

        // Calculate pulse duration
        int pulse_duration = pulse_end - pulse_start;

        // Check for timeout
        if (timeout_flag) {
            fprintf(stderr, "Timeout occurred\n");
            timeout_flag = 0; // Reset the flag for the next measurement
            continue;          // Skip distance calculation and retry
        }

        // Calculate distance in centimeters
        float distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance

        // Print distance to standard output
        printf("Distance: %.2f cm\n", distance);

        // Delay before next measurement
        gpioDelay(500); // 500ms delay
    }

    // This point should not be reached due to the infinite loop
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int ret;
    int current_value = -1; // Initialize to an invalid value

    // Register signal handler for SIGINT (Ctrl+C)
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Read current value (if possible, otherwise assume it's still the last set value)
        int new_value = -1; // Initialize to an invalid value
        if (gpiod_line_get_value(line) >= 0) {
            new_value = gpiod_line_get_value(line);
        } else {
            fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
        }

        // Check if the value has changed
        if (new_value != current_value) {
            // Apply the new value
            ret = gpiod_line_set_value(line, new_value);
            if (ret < 0) {
                fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
            } else {
                current_value = new_value;
                printf("GPIO %d: %s\n", GPIO_PIN, new_value ? "HIGH" : "LOW");
            }
        }

        // Sleep for a short interval
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define BMP280_ADDR 0x03
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESSURE_MSB 0xF7
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CALIB_00 0x88

#define I2C_DEVICE "/dev/i2c-1"

int i2c_fd;

// Calibration data
int16_t dig_T1;
int16_t dig_T2;
int16_t dig_T3;
uint16_t dig_P1;
int16_t dig_P2;
int16_t dig_P3;
int16_t dig_P4;
int16_t dig_P5;
int16_t dig_P6;
int16_t dig_P7;
int16_t dig_P8;
int16_t dig_P9;

// Function to read a single byte from I2C
int read_byte(int reg)
{
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    uint8_t buf[1];
    if (read(i2c_fd, buf, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return buf[0];
}

// Function to read multiple bytes from I2C
int read_bytes(int reg, uint8_t *buf, int len)
{
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP280
int read_calibration_data()
{
    uint8_t calib_data[26];
    if (read_bytes(BMP280_REG_CALIB_00, calib_data, 26) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
    }

    dig_T1 = (calib_data[1] << 8) | calib_data[0];
    dig_T2 = (calib_data[3] << 8) | (int8_t)calib_data[2];
    dig_T3 = (calib_data[5] << 8) | (int8_t)calib_data[4];
    dig_P1 = (calib_data[7] << 8) | calib_data[6];
    dig_P2 = (calib_data[9] << 8) | (int8_t)calib_data[8];
    dig_P3 = (calib_data[11] << 8) | (int8_t)calib_data[10];
    dig_P4 = (calib_data[13] << 8) | (int8_t)calib_data[12];
    dig_P5 = (calib_data[15] << 8) | (int8_t)calib_data[14];
    dig_P6 = (calib_data[17] << 8) | (int8_t)calib_data[16];
    dig_P7 = (calib_data[19] << 8) | (int8_t)calib_data[18];
    dig_P8 = (calib_data[21] << 8) | (int8_t)calib_data[20];
    dig_P9 = (calib_data[23] << 8) | (int8_t)calib_data[22];

    return 0;
}

// Function to read raw temperature and pressure values
int read_raw_data(int32_t *raw_temp, int32_t *raw_pressure)
{
    uint8_t data[6];
    if (read_bytes(BMP280_REG_PRESSURE_MSB, data, 6) != 0) {
        fprintf(stderr, "Failed to read raw data\n");
        return -1;
    }

    *raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    *raw_temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    return 0;
}

// Function to compensate temperature
float compensate_temperature(int32_t raw_temp)
{
    double var1, var2, T;
    var1 = (((double)raw_temp / 16384.0) - ((double)dig_T1) / 1024.0) * ((double)dig_T2);
    var2 = ((((double)raw_temp / 131072.0) - ((double)dig_T1) / 8192.0) * (((double)raw_temp / 131072.0) - ((double)dig_T1) / 8192.0)) * ((double)dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return (float)T;
}

// Function to compensate pressure
float compensate_pressure(int32_t raw_pressure, double t_fine)
{
    double var1, var2, p;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)dig_P4) * 65536.0);
    var1 = (((double)dig_P3) * var1 * var1 / 524288.0 + ((double)dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)dig_P1);

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)dig_P7)) / 16.0;

    return (float)(p / 100.0); // in hPa
}

int main()
{
    int32_t raw_temp, raw_pressure;
    float temperature, pressure;

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        close(i2c_fd);
        return 1;
    }

    // Set the BMP280 to forced mode
    uint8_t ctrl_meas = 0b00100011; // Oversampling x1, Normal mode
    if (write(i2c_fd, &ctrl_meas, 1) != 1) {
        perror("Failed to write control register");
        close(i2c_fd);
        return 1;
    }

    // Read temperature and pressure
    if (read_raw_data(&raw_temp, &raw_pressure) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Compensate temperature and pressure
    temperature = compensate_temperature(raw_temp);
    pressure = compensate_pressure(raw_pressure, temperature);

    printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temperature, pressure);

    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
