#include <string.h>

// Define the GPIO pins to be used
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24

// Define the chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *gpio17_line, *gpio22_line, *gpio23_line, *gpio24_line;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully.\n", sig);

    // Release GPIO lines
    if (gpio17_line) {
        gpiod_line_release(gpio17_line);
    }
    if (gpio22_line) {
        gpiod_line_release(gpio22_line);
    }
    if (gpio23_line) {
        gpiod_line_release(gpio23_line);
    }
    if (gpio24_line) {
        gpiod_line_release(gpio24_line);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int ret;
    unsigned int value;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    gpio17_line = gpiod_chip_get_line(chip, GPIO_17);
    gpio22_line = gpiod_chip_get_line(chip, GPIO_22);
    gpio23_line = gpiod_chip_get_line(chip, GPIO_23);
    gpio24_line = gpiod_chip_get_line(chip, GPIO_24);

    if (!gpio17_line || !gpio22_line || !gpio23_line || !gpio24_line) {
        perror("Error getting GPIO line");
        // Release already acquired lines
        if(gpio17_line) gpiod_line_release(gpio17_line);
        if(gpio22_line) gpiod_line_release(gpio22_line);
        if(gpio23_line) gpiod_line_release(gpio23_line);
        if(gpio24_line) gpiod_line_release(gpio24_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(gpio17_line, "gpio_output", 0);
    ret |= gpiod_line_request_output(gpio22_line, "gpio_output", 0);
    ret |= gpiod_line_request_output(gpio23_line, "gpio_output", 0);
    ret |= gpiod_line_request_output(gpio24_line, "gpio_output", 0);

    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        // Release already acquired lines
        if(gpio17_line) gpiod_line_release(gpio17_line);
        if(gpio22_line) gpiod_line_release(gpio22_line);
        if(gpio23_line) gpiod_line_release(gpio23_line);
        if(gpio24_line) gpiod_line_release(gpio24_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the current state of the GPIO lines
        value = gpiod_line_get_value(gpio17_line);
        value |= (gpiod_line_get_value(gpio22_line) << 1);
        value |= (gpiod_line_get_value(gpio23_line) << 2);
        value |= (gpiod_line_get_value(gpio24_line) << 3);

        // Print the current state
        printf("GPIO17: %d, GPIO22: %d, GPIO23: %d, GPIO24: %d\n",
               value & 1, (value >> 1) & 1, (value >> 2) & 1, (value >> 3) & 1);

        // Toggle the state of GPIO17
        ret = gpiod_line_set_value(gpio17_line, !value & 1);
        if (ret < 0) {
            perror("Error setting GPIO17 value");
            break;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Release GPIO lines and close chip (in case of error)
    if(gpio17_line) gpiod_line_release(gpio17_line);
    if(gpio22_line) gpiod_line_release(gpio22_line);
    if(gpio23_line) gpiod_line_release(gpio23_line);
    if(gpio24_line) gpiod_line_release(gpio24_line);
    if(chip) gpiod_chip_close(chip);

    return 1;
}

#include <stdio.h>
