        perror("Failed to write register address for calibration data");
        return -1;
    }
    if (read(i2c_fd, buffer, 26) != 26) {
        perror("Failed to read calibration data");
        return -1;
    }

    dig_T1 = (buffer[1] << 8) | buffer[0];
    dig_T2 = (buffer[3] << 8) | buffer[2];
    dig_T3 = (buffer[5] << 8) | buffer[4];
    dig_P1 = (buffer[7] << 8) | buffer[6];
    dig_P2 = (buffer[9] << 8) | buffer[8];
    dig_P3 = (buffer[11] << 8) | buffer[10];
    dig_P4 = (buffer[13] << 8) | buffer[12];
    dig_P5 = (buffer[15] << 8) | buffer[14];
    dig_P6 = (buffer[17] << 8) | buffer[16];
    dig_P7 = (buffer[19] << 8) | buffer[18];
    dig_P8 = (buffer[21] << 8) | buffer[20];
    dig_P9 = (buffer[23] << 8) | buffer[22];
    dig_H1 = buffer[25];

    unsigned char buffer_h[7];
    if (write(i2c_fd, (unsigned char[]){0xE1}, 1) != 1) {
        perror("Failed to write register address for humidity calibration data");
        return -1;
    }
    if (read(i2c_fd, buffer_h, 7) != 7) {
        perror("Failed to read humidity calibration data");
        return -1;
    }

    dig_H2 = (buffer_h[1] << 8) | buffer_h[0];
    dig_H3 = buffer_h[2];
    dig_H4 = (buffer_h[3] << 4) | (buffer_h[4] & 0x0F);
    dig_H5 = (buffer_h[5] << 4) | (buffer_h[4] >> 4);
    dig_H6 = buffer_h[6];

    return 0;
}

// Function to read raw temperature, pressure, and humidity data
int read_raw_data(int32_t *temperature, int32_t *pressure, int32_t *humidity)
{
    unsigned char buffer[8];

    if (write(i2c_fd, (unsigned char[]){BME280_REG_PRESSURE_MSB}, 1) != 1) {
        perror("Failed to write register address for raw data");
        return -1;
    }
    if (read(i2c_fd, buffer, 8) != 8) {
        perror("Failed to read raw data");
        return -1;
    }

    *pressure = (buffer[0] << 12) | (buffer[1] << 4) | (buffer[2] >> 4);
    *temperature = (buffer[3] << 12) | (buffer[4] << 4) | (buffer[5] >> 4);
    *humidity = (buffer[6] << 8) | buffer[7];

    return 0;
}

// Function to compensate temperature
float compensate_temperature(int32_t raw_temperature)
{
    double var1, var2, T;
    var1 = (((double)raw_temperature) / 16384.0 - ((double)dig_T1) / 1024.0) * ((double)dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)dig_T1) / 8192.0)) * ((double)dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return (float)T;
}

// Function to compensate pressure
float compensate_pressure(int32_t raw_pressure, double t_fine)
{
    double var1, var2, p;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)dig_P4) * 65536.0);
    var1 = (((double)dig_P3) * var1 * var1 / 524288.0 + ((double)dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)dig_P7)) / 16.0;
    return (float)(p/100.0); // Return in hPa
}

// Function to compensate humidity
float compensate_humidity(int32_t raw_humidity, double t_fine)
{
    double var_H;
    var_H = (((double)t_fine) - 76800.0);
    var_H = (raw_humidity - (((double)dig_H4) * 64.0 + ((double)dig_H5) / 16384.0 * var_H)) * (((double)dig_H2) / 65536.0 * (1.0 + ((double)dig_H6) / 67108864.0 * var_H * (1.0 + ((double)dig_H3) / 67108864.0 * var_H)));
    var_H = var_H * (1.0 - ((double)dig_H1) * var_H / 524288.0);
    if (var_H > 100.0)
    {
        var_H = 100.0;
    } else if (var_H < 0.0)
    {
        var_H = 0.0;
    }
    return (float)var_H;
}

int main()
{
    struct timespec sleep_time = {5, 0}; // 5 seconds
    int32_t raw_temperature, raw_pressure, raw_humidity;
    float temperature, pressure, humidity;
    unsigned char id;

    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Check BME280 ID
    if (read_byte(BME280_REG_ID, &id) != 0) {
        fprintf(stderr, "Error reading BME280 ID\n");
        close(i2c_fd);
        return 1;
    }

    if (id != 0x60) {
        fprintf(stderr, "Incorrect BME280 ID: 0x%02X\n", id);
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        close(i2c_fd);
        return 1;
    }

    // Set oversampling and power mode
    unsigned char ctrl_meas = (OVERSAMPLING_TEMP << 5) | (OVERSAMPLING_PRESS << 2) | 3; // Normal mode
    unsigned char ctrl_hum = OVERSAMPLING_HUM;

    if (write_byte(BME280_REG_CTRL_HUM, ctrl_hum) != 0) {
        fprintf(stderr, "Error writing to CTRL_HUM register\n");
        close(i2c_fd);
        return 1;
    }

    if (write_byte(BME280_REG_CTRL_MEAS, ctrl_meas) != 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        close(i2c_fd);
        return 1;
    }

    // Read 3 measurements with 5-second intervals
    for (int i = 0; i < 3; ++i) {
        if (read_raw_data(&raw_temperature, &raw_pressure, &raw_humidity) == 0) {
            temperature = compensate_temperature(raw_temperature);
            pressure = compensate_pressure(raw_pressure, (double)raw_temperature); // Pass raw_temperature to compensate_pressure
            humidity = compensate_humidity(raw_humidity, (double)raw_temperature); // Pass raw_temperature to compensate_humidity

            printf("Temperature: %.2f °C, Pressure: %.2f hPa, Humidity: %.2f %%\n", temperature, pressure, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    int ret;
    int value;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d output control started. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (keep_running) {
        // Set GPIO value to 1
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO value to 1: %s\n", strerror(errno));
            break; // Exit loop on error
        }
        value = 1;

        // Report GPIO value
        printf("GPIO %d: %d\n", GPIO_PIN, value);

        // Wait for 1 second
        sleep(1);

        // Set GPIO value to 0
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO value to 0: %s\n", strerror(errno));
            break; // Exit loop on error
        }
        value = 0;

        // Report GPIO value
        printf("GPIO %d: %d\n", GPIO_PIN, value);

        // Wait for 1 second
        sleep(1);
    }

    // Release GPIO line
    if (line) {
        gpiod_line_release(line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("GPIO %d output control stopped.\n", GPIO_PIN);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define VEML7700_ADDR 0x10
#define ALS_DATA_REG 0x04

int i2c_fd;
volatile sig_atomic_t stop_flag = 0;

void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully.\n", sig);
    stop_flag = 1;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 0.5 seconds

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    printf("VEML7700 reader started. Press Ctrl+C to exit.\n");

    while (!stop_flag) {
        // Read ALS data
        unsigned char data[2];
        if (read(i2c_fd, data, 2) != 2) {
            perror("Error reading ALS data");
            break; // Exit loop on error
        }

        // Combine the two bytes into a 16-bit value
        unsigned int als_value = (data[1] << 8) | data[0];

        // Print the ALS value
        printf("ALS: %u\n", als_value);

        // Sleep for 0.5 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep failed");
            break; // Exit loop on error
        }
    }

    // Close I2C device
    close(i2c_fd);
    printf("VEML7700 reader stopped.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B9600

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting...\n", signal);
}

int setup_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 9600 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = setup_uart(UART_DEVICE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    printf("UART initialized on %s. Reading data...\n", UART_DEVICE);

    char buffer[256];
    ssize_t bytes_read;
    struct timespec sleep_time = {0, 100000000}; // 0.1 seconds

    while (program_running) {
        bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s\n", buffer);
        } else if (bytes_read == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // No data available, sleep briefly
                nanosleep(&sleep_time, NULL);
            } else {
                perror("Error reading from UART");
                break;
            }
        }
    }

    if (uart_fd != -1) {
        close(uart_fd);
        printf("UART port closed.\n");
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        // Trigger the sensor
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10); // 10 us trigger pulse
        gpioWrite(TRIGGER_PIN, 0);

        // Measure the echo pulse width
        uint32_t start_tick = gpioTick();
        while (gpioRead(ECHO_PIN) == 0) {
            if (gpioTick() - start_tick > 50000) { // Timeout after 50ms
                fprintf(stderr, "Timeout waiting for echo start\n");
                continue; // Retry
            }
        }
        uint32_t echo_start = gpioTick();

        while (gpioRead(ECHO_PIN) == 1) {
            if (gpioTick() - echo_start > 50000) { // Timeout after 50ms
                fprintf(stderr, "Timeout waiting for echo end\n");
                continue; // Retry
            }
        }
        uint32_t echo_end = gpioTick();

        uint32_t pulse_width = echo_end - echo_start;

        // Calculate distance in centimeters
        float distance = (pulse_width * 0.0343) / 2.0;

        // Validate the distance
        if (distance < 2.0 || distance > 400.0) {
            fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
            continue; // Retry
        }

        printf("Distance: %.2f cm\n", distance);

        gpioDelay(500); // Wait 0.5 seconds
    }

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    int ret;
    int value;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

