}

#include <stdio.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define ADXL345_ADDR 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32

int main() {
    const char* i2c_dev = "/dev/i2c-1";
    int fd = open(i2c_dev, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave.");
        close(fd);
        return 1;
    }

    // Initialize ADXL345
    uint8_t init_data[2] = {POWER_CTL, 0x08}; // Enable measurement
    if (write(fd, init_data, 2) != 2) {
        perror("Failed to write to I2C device");
        close(fd);
        return 1;
    }

    init_data[0] = DATA_FORMAT;
    init_data[1] = 0x08; // +/- 2g range
    if (write(fd, init_data, 2) != 2) {
        perror("Failed to write to I2C device");
        close(fd);
        return 1;
    }

    uint8_t data[6];
    if (read(fd, data, 6) != 6) {
        perror("Failed to read from I2C device");
        close(fd);
        return 1;
    }

    int16_t x = (data[1] << 8) | data[0];
    int16_t y = (data[3] << 8) | data[2];
    int16_t z = (data[5] << 8) | data[4];

    printf("X: %d, Y: %d, Z: %d\n", x, y, z);

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the GPIO pins to control
#define GPIO_PINS {4, 17, 18, 22, 23, 24, 25, 27}

// Structure to hold GPIO chip and line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[8]; // Assuming a maximum of 8 GPIO pins
} gpio_context_t;

// Global variable to store the GPIO context
gpio_context_t gpio_context;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < 8; i++) {
        if (gpio_context.lines[i]) {
            gpiod_line_release(gpio_context.lines[i]);
        }
    }

    // Close the GPIO chip
    if (gpio_context.chip) {
        gpiod_chip_close(gpio_context.chip);
    }

    exit(0);
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to report the state of all GPIO pins
void report_gpio_state() {
    for (int i = 0; i < 8; i++) {
        if (gpio_context.lines[i]) {
            int value = gpiod_line_get_value(gpio_context.lines[i]);
            printf("GPIO %d: %d\n", i + 1, value);
        }
    }
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    gpio_context.chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_context.chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the GPIO lines
    int gpio_pins[] = GPIO_PINS;
    for (int i = 0; i < 8; i++) {
        gpio_context.lines[i] = gpiod_chip_get_line(gpio_context.chip, gpio_pins[i]);
        if (!gpio_context.lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", gpio_pins[i], strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(gpio_context.lines[j]);
            }
            gpiod_chip_close(gpio_context.chip);
            return 1;
        }

        // Request the line for output
        int ret = gpiod_line_request_output(gpio_context.lines[i], "gpio_output", 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", gpio_pins[i], strerror(-ret));
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(gpio_context.lines[j]);
            }
            gpiod_chip_close(gpio_context.chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        // Set the state of each GPIO pin to the opposite of its current state
        for (int i = 0; i < 8; i++) {
            if (gpio_context.lines[i]) {
                int current_value = gpiod_line_get_value(gpio_context.lines[i]);
                if (current_value < 0) {
                    fprintf(stderr, "Error getting GPIO value: %s\n", strerror(-current_value));
                    break; // Exit loop on error
                }
                int new_value = (current_value == 0) ? 1 : 0;
                if (set_gpio_state(gpio_context.lines[i], new_value) < 0) {
                    break; // Exit loop on error
                }
            }
        }

        // Report the state of all GPIO pins
        report_gpio_state();

        // Wait for 0.05 seconds
