        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO17, strerror(errno));
            break; // Exit loop on error
        }

        // Toggle GPIO 21
        ret = gpiod_line_set_value(gpio21_line, !value);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO21, strerror(errno));
            break; // Exit loop on error
        }

        // Wait 0.1 seconds
