#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the GPIO pins to control
#define GPIO_PINS {0, 1, 2, 3, 4, 5, 12, 17}

// Structure to hold GPIO chip and line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[8]; // Assuming a maximum of 8 GPIO pins
} gpio_state_t;

// Global variable to store the GPIO state
gpio_state_t gpio_state;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < 8; i++) {
        if (gpio_state.lines[i]) {
            gpiod_line_release(gpio_state.lines[i]);
            printf("Released GPIO %d\n", i);
        }
    }

    // Close the GPIO chip
    if (gpio_state.chip) {
        gpiod_chip_close(gpio_state.chip);
        printf("Closed GPIO chip\n");
    }

    exit(0);
}

// Function to set the state of a GPIO pin
int set_gpio_state(gpio_state_t *gpio_state, int pin, int value) {
    if (pin < 0 || pin > 7) {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", pin);
        return -1;
    }

    if (!gpio_state->lines[pin]) {
        fprintf(stderr, "Error: GPIO pin %d not initialized\n", pin);
        return -1;
    }

    int ret = gpiod_line_set_value(gpio_state->lines[pin], value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d value: %s\n", pin, strerror(-ret));
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    gpio_state.chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_state.chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    printf("GPIO chip opened successfully\n");

    // Get the GPIO lines
    for (int i = 0; i < 8; i++) {
        gpio_state.lines[i] = gpiod_chip_get_line(gpio_state.chip, i);
        if (!gpio_state.lines[i]) {
            fprintf(stderr, "Error getting GPIO %d line: %s\n", i, strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(gpio_state.lines[j]);
            }
            gpiod_chip_close(gpio_state.chip);
            return 1;
        }

        // Request the line for output
        int ret = gpiod_line_request_output(gpio_state.lines[i], "gpio-output", 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO %d line for output: %s\n", i, strerror(-ret));
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(gpio_state.lines[j]);
            }
            gpiod_chip_close(gpio_state.chip);
            return 1;
        }
    }

    printf("GPIO lines acquired and requested for output\n");

    // Main loop
    while (1) {
        for (int i = 0; i < 8; i++) {
            // Toggle the state of the GPIO pin
            int current_value = (i % 2 == 0) ? 0 : 1;
            if (set_gpio_state(&gpio_state, i, current_value) != 0) {
                fprintf(stderr, "Error setting GPIO %d state\n", i);
            }
        }

        sleep(1);
    }

    return 0;
