void echo_callback(int gpio, int level, uint32_t tick)
{
    if (gpio == ECHO_PIN)
    {
        if (level == 1) // Rising edge
        {
            start_tick = tick;
        }
        else if (level == 0) // Falling edge
        {
            // Calculate pulse width in microseconds
            uint32_t pulse_width = tick - start_tick;

            // Calculate distance in centimeters (speed of sound: 343 m/s)
            // distance = (pulse_width * 0.000001) * 34300 / 2
            float distance = (pulse_width * 0.000001) * 34300 / 2.0;

            // Print the distance
            printf("Distance: %.2f cm\n", distance);
        }
    }
}

