// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define MOTION_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 50000      // 50ms timeout

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
void trigger_pulse();
float get_distance();
void motion_detected_callback(int gpio, int level, uint32_t tick);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure distance using the HC-SR04
float get_distance() {
    long long start_tick, end_tick, diff_tick;

    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal not received (timeout)\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1);
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal did not go low (timeout)\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Callback function for motion detection
void motion_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge detected
        printf("Motion detected!\n");
        trigger_pulse();
        float distance = get_distance();
        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            printf("Error: Distance measurement failed.\n");
        }
    }
}

