        return -1;
    }
    return 0;
}

// Function to read a register
int read_register(int fd, uint8_t reg, uint8_t *value)
{
    uint8_t buf[1];
    buf[0] = TCS34725_COMMAND_BIT | reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *value = buf[0];
    return 0;
}

// Function to initialize the TCS34725
int init_tcs34725(int fd)
{
    uint8_t id;

    // Check the ID register
    if (read_register(fd, TCS34725_ID, &id) != 0) {
        fprintf(stderr, "Error reading ID register\n");
        return -1;
    }

    if (id != 0x44) {
        fprintf(stderr, "Incorrect ID value: 0x%02X\n", id);
        return -1;
    }

    // Set integration time
    if (write_register(fd, TCS34725_ATIME, TCS34725_INTEGRATIONTIME_24MS) != 0) {
        fprintf(stderr, "Error setting integration time\n");
        return -1;
    }

    // Set gain
    if (write_register(fd, TCS34725_CONTROL, TCS34725_GAIN_1X) != 0) {
        fprintf(stderr, "Error setting gain\n");
        return -1;
    }

    // Enable power and ALS
    if (write_register(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0) {
        fprintf(stderr, "Error enabling device\n");
        return -1;
    }

    return 0;
}

// Function to read RGBC values
int read_rgbc(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c)
{
    uint8_t buf[8];

    // Read all RGBC values in one go
    if (write(fd, (uint8_t[]){TCS34725_COMMAND_BIT | TCS34725_CDATA}, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }
    if (read(fd, buf, 8) != 8) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *c = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    *r = (uint16_t)buf[2] | ((uint16_t)buf[3] << 8);
    *g = (uint16_t)buf[4] | ((uint16_t)buf[5] << 8);
    *b = (uint16_t)buf[6] | ((uint16_t)buf[7] << 8);

    return 0;
}

int main()
{
    const char *i2c_device = "/dev/i2c-1"; // I2C device file

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize the TCS34725
    if (init_tcs34725(i2c_fd) != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("TCS34725 sensor reader started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        uint16_t r, g, b, c;

        // Read RGBC values
        if (read_rgbc(i2c_fd, &r, &g, &b, &c) == 0) {
            // Print the values
            printf("R: %5u, G: %5u, B: %5u, C: %5u\n", r, g, b, c);
        } else {
            fprintf(stderr, "Failed to read RGBC values\n");
        }

        // Wait for 0.5 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Disable the sensor before exiting
    write_register(i2c_fd, TCS34725_ENABLE, 0x00);

    // Close the I2C device
    close(i2c_fd);

    printf("TCS34725 sensor reader stopped.\n");

    return EXIT_SUCCESS;
}

