#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the GPIO pins to be used
#define GPIO_PINS {4, 17, 18, 22, 23, 24, 27}

// Structure to hold GPIO chip and line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[7]; // Assuming a maximum of 7 GPIO pins
} gpio_config_t;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to report the state of all GPIO pins
void report_gpio_state(gpio_config_t *config) {
    for (int i = 0; i < 7; ++i) {
        int value = gpiod_line_get_value(config->lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error getting GPIO value: %s\n", strerror(-value));
            continue; // Continue to the next pin
        }
        printf("GPIO %d: %s\n", i + 1, value ? "HIGH" : "LOW");
    }
}

int main() {
    // Install signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Initialize libgpiod
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    gpio_config_t gpio_config = {chip, {NULL}};

    // Get lines for each GPIO pin
    int gpio_pins[] = GPIO_PINS;
    for (size_t i = 0; i < sizeof(gpio_pins) / sizeof(gpio_pins[0]); ++i) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!line) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", gpio_pins[i], strerror(errno));
            // Cleanup already initialized lines
            for (int j = 0; j < i; ++j) {
                gpiod_line_release(gpio_config.lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        int ret = gpiod_line_request_output(line, "gpio_control", 0); // Initial value LOW
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", gpio_pins[i], strerror(-ret));
            gpiod_line_release(line);
            // Cleanup already initialized lines
            for (int j = 0; j < i; ++j) {
                gpiod_line_release(gpio_config.lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        gpiod_line_set_value(line, 0); // Set initial value to LOW
        gpio_config.lines[i] = line;
    }

    // Main loop to toggle GPIO pins
    while (program_running) {
        report_gpio_state(&gpio_config);

        // Toggle the state of each GPIO pin
        for (int i = 0; i < 7; ++i) {
            int current_value = gpiod_line_get_value(gpio_config.lines[i]);
            if (current_value < 0) {
                fprintf(stderr, "Error getting GPIO value during toggle: %s\n", strerror(-current_value));
                continue; // Skip to the next pin
            }

            if (set_gpio_state(gpio_config.lines[i], !current_value) < 0) {
                fprintf(stderr, "Error toggling GPIO %d\n", i + 1);
            }
        }

        sleep(1); // Wait for 1 second
    }

    // Release GPIO lines and close the chip
    for (int i = 0; i < 7; ++i) {
        if (gpio_config.lines[i]) {
            gpiod_line_release(gpio_config.lines[i]);
        }
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

