    } else {
        fprintf(stderr, "GPIO %d not available or not a GPIO\n", PWM_GPIO);
        gpioTerminate();
        return 1;
    }

    /* Set GPIO 2 as output */
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    /* Set PWM frequency */
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    /* Set PWM range (0-255) */
    gpioSetPWMrange(PWM_GPIO, 255);

    /* Set PWM duty cycle (50%) */
    gpioPWM(PWM_GPIO, 128); // 50% duty cycle (128/255)

    /* Register signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Main loop */
    while (!terminate) {
        printf("PWM on GPIO %d is set to 50%% duty cycle\n", PWM_GPIO);
        gpioDelay(5000000); // Wait 5 seconds
    }

    /* Clean up and exit */
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate(); // Terminate pigpio
    printf("Program terminated cleanly.\n");
    return 0;
