#define GPIOCHIP "gpiochip0"
#define GPIO_LINE_1 3
#define GPIO_LINE_2 5

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *line1 = NULL;
struct gpiod_line *line2 = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully...\n", sig);

    // Release GPIO lines
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int ret;
    int current_state1 = 0;
    int current_state2 = 0;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line 1
    line1 = gpiod_chip_get_line(chip, GPIO_LINE_1);
    if (!line1) {
        perror("Error getting GPIO line 1");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line 2
    line2 = gpiod_chip_get_line(chip, GPIO_LINE_2);
    if (!line2) {
        perror("Error getting GPIO line 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line 1 as output
    ret = gpiod_line_request_output(line1, "gpio_output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 1 as output");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line 2 as output
    ret = gpiod_line_request_output(line2, "gpio_output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 2 as output");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle the state of GPIO line 1
        current_state1 = !current_state1;
        ret = gpiod_line_set_value(line1, current_state1);
        if (ret < 0) {
            perror("Error setting GPIO line 1 value");
            break;
        }

        // Print the current state of GPIO line 1
        printf("GPIO %d: %s\n", GPIO_LINE_1, current_state1 ? "HIGH" : "LOW");

        // Delay for 1 second
        sleep(1);

        // Toggle the state of GPIO line 2
        current_state2 = !current_state2;
        ret = gpiod_line_set_value(line2, current_state2);
        if (ret < 0) {
            perror("Error setting GPIO line 2 value");
            break;
        }

        // Print the current state of GPIO line 2
        printf("GPIO %d: %s\n", GPIO_LINE_2, current_state2 ? "HIGH" : "LOW");

        // Delay for 1 second
        sleep(1);
    }

    // Release GPIO lines and close chip before exiting
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 50000      // 50ms timeout

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile int echo_start_time = 0;
static volatile int echo_end_time = 0;
static volatile int echo_received = 0;
static volatile int program_running = 1;

// Function prototypes
int gpio_init(void);
void trigger_pulse(void);
void echo_callback(int gpiod_line, int event);
float calculate_distance(int pulse_width);
void report_state(float distance);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    program_running = 0;

    // Release GPIO lines
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Initialize GPIO pins
int gpio_init(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request trigger line as output
    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request echo line as input
    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Error requesting echo line as input");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Set initial trigger state to low
    gpiod_line_set_value(trigger_line, 0);

    // Set up interrupt callback for echo line
    if (gpiod_line_request_rising_edge_events(echo_line, "echo_rising") < 0) {
        perror("Error requesting rising edge events for echo line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_falling_edge_events(echo_line, "echo_falling") < 0) {
        perror("Error requesting falling edge events for echo line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Generate a 10us trigger pulse
void trigger_pulse(void) {
    gpiod_line_set_value(trigger_line, 1);
    usleep(10); // 10us
    gpiod_line_set_value(trigger_line, 0);
}

// Callback function for echo line events
void echo_callback(int gpiod_line, int event) {
    struct timespec ts;

    if (event == GPIOD_LINE_EVENT_RISING_EDGE) {
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
            echo_start_time = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
            echo_received = 1; // Indicate rising edge received
        } else {
            perror("clock_gettime failed");
        }
    } else if (event == GPIOD_LINE_EVENT_FALLING_EDGE) {
        if (echo_received && clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
            echo_end_time = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
        } else {
            perror("clock_gettime failed");
        }
        echo_received = 0; // Reset flag
    }
}

// Calculate distance in centimeters
float calculate_distance(int pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Report distance to standard output
void report_state(float distance) {
    printf("Distance: %.2f cm\n", distance);
}

int main(void) {
    // Set up signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("HC-SR04 Distance Sensor\n");

    // Main loop
    while (program_running) {
        echo_start_time = 0;
        echo_end_time = 0;
        echo_received = 0;

        // Trigger the sensor
        trigger_pulse();

        // Wait for echo or timeout
        int timeout_count = 0;
        while (echo_end_time == 0 && timeout_count < TIMEOUT_US) {
            usleep(1); // Check every microsecond
            timeout_count++;
        }

        if (echo_end_time == 0) {
            fprintf(stderr, "Timeout waiting for echo.\n");
            continue; // Skip to the next iteration
        }

        // Calculate pulse width
        int pulse_width = echo_end_time - echo_start_time;

        // Calculate distance
        float distance = calculate_distance(pulse_width);

        // Report state
        report_state(distance);

        // Delay before next measurement
        usleep(100000); // 100ms
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    keep_running = 0;
}

int main() {
    int ret;
    unsigned int value;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line, "gpio-output", 0) < 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d output control\n", GPIO_PIN);

    while (keep_running) {
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            fprintf(stderr, "Error reading line value: %s\n", strerror(errno));
            break;
        }

        value = ret;

        if (value != 0 && value != 1) {
            fprintf(stderr, "Invalid value read: %u\n", value);
            continue; // Skip to the next iteration
        }

        printf("GPIO %d is %s\n", GPIO_PIN, (value == 1) ? "HIGH" : "LOW");
        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO %d output control terminated.\n", GPIO_PIN);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", rc);
        return 1;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_PIN, 1000); // 1 kHz

    while (!terminate) {
        gpioPWM(GPIO_PIN, 128); // 50% duty cycle
        printf("PWM: 128\n");
        usleep(200000); // 0.2 seconds

        gpioPWM(GPIO_PIN, 0); // 0% duty cycle
        printf("PWM: 0\n");
        usleep(200000); // 0.2 seconds
    }

    gpioPWM(GPIO_PIN, 0); // Ensure PWM is off before exiting
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIOCHIP "gpiochip0"
#define GPIO17 17
#define GPIO18 18

static struct gpiod_chip *chip;
static struct gpiod_line *gpio17_line;
static struct gpiod_line *gpio18_line;
static volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int ret;
    unsigned int value;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get GPIO 17 line
    gpio17_line = gpiod_chip_get_line(chip, GPIO17);
    if (!gpio17_line) {
        perror("gpiod_chip_get_line (GPIO17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get GPIO 18 line
    gpio18_line = gpiod_chip_get_line(chip, GPIO18);
    if (!gpio18_line) {
        perror("gpiod_chip_get_line (GPIO18)");
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 17 as output
    ret = gpiod_line_request_output(gpio17_line, "gpio17_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO17)");
        gpiod_line_release(gpio18_line);
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 18 as output
    ret = gpiod_line_request_output(gpio18_line, "gpio18_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO18)");
        gpiod_line_release(gpio17_line);
        gpiod_line_release(gpio18_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Read current state of GPIO 17
        ret = gpiod_line_get_value(gpio17_line);
        if (ret < 0) {
            perror("gpiod_line_get_value (GPIO17)");
            break; // Exit loop on error
        }
        value = ret;

        // Read current state of GPIO 18
        ret = gpiod_line_get_value(gpio18_line);
        if (ret < 0) {
            perror("gpiod_line_get_value (GPIO18)");
            break; // Exit loop on error
        }
        value |= (ret << 1); // Shift and OR to combine values

        // Print the combined value
        printf("GPIO17: %d, GPIO18: %d, Combined: %d\n",
               gpiod_line_get_value(gpio17_line),
               gpiod_line_get_value(gpio18_line),
               value);

        // Toggle GPIO 17
        ret = gpiod_line_set_value(gpio17_line, !gpiod_line_get_value(gpio17_line));
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO17)");
            break; // Exit loop on error
        }

        // Toggle GPIO 18
        ret = gpiod_line_set_value(gpio18_line, !gpiod_line_get_value(gpio18_line));
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO18)");
            break; // Exit loop on error
        }

        // Wait 500ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 500ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    gpiod_line_release(gpio17_line);
    gpiod_line_release(gpio18_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the GPIO pins to be used
#define GPIO_PIN_1 18
#define GPIO_PIN_2 23
#define GPIO_PIN_3 24

// Define the chip name (adjust if necessary)
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *gpio_line_1, *gpio_line_2, *gpio_line_3;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully...\n", sig);

    // Release GPIO lines
    if (gpio_line_1) {
        gpiod_line_release(gpio_line_1);
    }
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }
    if (gpio_line_3) {
        gpiod_line_release(gpio_line_3);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int ret;
    unsigned int value;

    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", CHIP_NAME, strerror(errno));
        return 1;
    }

    // Get the GPIO lines
    gpio_line_1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    gpio_line_2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    gpio_line_3 = gpiod_chip_get_line(chip, GPIO_PIN_3);

    if (!gpio_line_1 || !gpio_line_2 || !gpio_line_3) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        // Release any previously acquired lines
        if (gpio_line_1) gpiod_line_release(gpio_line_1);
        if (gpio_line_2) gpiod_line_release(gpio_line_2);
        if (gpio_line_3) gpiod_line_release(gpio_line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines for output
    ret = gpiod_line_request_output(gpio_line_1, "gpio_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_PIN_1, strerror(errno));
        goto cleanup;
    }
    ret = gpiod_line_request_output(gpio_line_2, "gpio_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_PIN_2, strerror(errno));
        goto cleanup;
    }
    ret = gpiod_line_request_output(gpio_line_3, "gpio_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_PIN_3, strerror(errno));
        goto cleanup;
    }

    // Main loop
    while (1) {
        // Set the GPIO values
        ret = gpiod_line_set_value(gpio_line_1, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_PIN_1, strerror(errno));
            goto cleanup;
        }
        ret = gpiod_line_set_value(gpio_line_2, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_PIN_2, strerror(errno));
            goto cleanup;
        }
        ret = gpiod_line_set_value(gpio_line_3, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_PIN_3, strerror(errno));
            goto cleanup;
        }

        // Print the current state
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, (int)gpiod_line_get_value(gpio_line_1), GPIO_PIN_2, (int)gpiod_line_get_value(gpio_line_2), GPIO_PIN_3, (int)gpiod_line_get_value(gpio_line_3));

        // Wait for 0.1 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

cleanup:
    // Release GPIO lines
    if (gpio_line_1) {
        gpiod_line_release(gpio_line_1);
    }
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }
    if (gpio_line_3) {
        gpiod_line_release(gpio_line_3);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 1;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <stdint.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

int i2c_fd;

void signal_handler(int sig);
int init_mpu6050();
int read_mpu6050(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z);

int main() {
    signal(SIGINT, signal_handler);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    int16_t accel_x, accel_y, accel_z;
    while (1) {
        if (read_mpu6050(&accel_x, &accel_y, &accel_z) == 0) {
            printf("AccelX: %d, AccelY: %d, AccelZ: %d\n", accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Failed to read MPU6050 data.\n");
        }
        sleep(1);
    }

    return 0;
}

void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    close(i2c_fd);
    exit(0);
}

int init_mpu6050() {
    // Wake up the MPU6050 (set sleep bit to 0)
    uint8_t data = 0x00;
    if (write(i2c_fd, &data, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int read_mpu6050(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    uint8_t buffer[6];

    // Read accelerometer data (6 bytes)
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Combine high and low bytes for each axis
    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

