    }

    printf("GPIO %d output control started. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (keep_running) {
        value = !value; // Toggle the value
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d is now %s\n", GPIO_PIN, value ? "HIGH" : "LOW");
        usleep(600000); // 0.6 seconds
    }

    printf("Releasing GPIO %d...\n", GPIO_PIN);

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}
